//Define object type keywords. matches any variable that contains these substrings/patterns
//does not care about case sensitivity but all patterns should be in lowercase to properly match.

const objectTypePatterns = {
    //first one is matched first to avoid misdetections. thus piece end should be before piece.
    'iterator': ['thereisnopredefinedpatternforthisobjecttype'],
    'edge': ['thereisnopredefinedpatternforthisobjecttype'],
    'selemobj': ['thereisnopredefinedpatternforthisobjecttype'],
    'profileend': ['thereisnopredefinedpatternforthisobjecttype'],
    'vxgeom': ['thereisnopredefinedpatternforthisobjecttype'],
    'profile': ['thereisnopredefinedpatternforthisobjecttype'],
    'sheet': ['thereisnopredefinedpatternforthisobjecttype'],
    'area': ['thereisnopredefinedpatternforthisobjecttype'],
    'joint': ['thereisnopredefinedpatternforthisobjecttype'],
    'point': ['thereisnopredefinedpatternforthisobjecttype'],
    'slope': ['thereisnopredefinedpatternforthisobjecttype'],
    'polyline': ['thereisnopredefinedpatternforthisobjecttype'],
    'array': ['thereisnopredefinedpatternforthisobjecttype'],
    'value': ['thereisnopredefinedpatternforthisobjecttype'],
    'wall': ['thereisnopredefinedpatternforthisobjecttype'],
    'boolean': ['thereisnopredefinedpatternforthisobjecttype'],
    'pvector': ['thereisnopredefinedpatternforthisobjecttype'],
    'xvector': ['thereisnopredefinedpatternforthisobjecttype'],
    'yvector': ['thereisnopredefinedpatternforthisobjecttype'],
    'zvector': ['thereisnopredefinedpatternforthisobjecttype'],
    'nvector': ['thereisnopredefinedpatternforthisobjecttype'],
    //2d "objects":
    'line': ['thereisnopredefinedpatternforthisobjecttype'],
    'hatch': ['thereisnopredefinedpatternforthisobjecttype'],
    'text': ['thereisnopredefinedpatternforthisobjecttype'],
    //direction vector
    'dvector': ['thereisnopredefinedpatternforthisobjecttype'],
    //macro object
    'macro': ['thereisnopredefinedpatternforthisobjecttype'],
    'databaselist': ['thereisnopredefinedpatternforthisobjecttype'],
    'database': ['thereisnopredefinedpatternforthisobjecttype'],
    'validatedCommand': ['thereisnopredefinedpatternforthisobjecttype'],
    //'material': ['mat', 'material', 'mtl']
};

const objectTypeIndexMap = new Map();
const patternToObjectTypeMap = new Map();
Object.keys(objectTypePatterns).forEach((key, index) => {
    objectTypeIndexMap.set(key, index + 1);
});
for (const [objectType, patterns] of Object.entries(objectTypePatterns)) {
    for (const pattern of patterns) {
        if (pattern !== 'thereisnopredefinedpatternforthisobjecttype') {
            patternToObjectTypeMap.set(pattern, objectType);
        }
    }
}

// Create a reverse lookup map for faster bracket content matching
const bracketContentToTypeMap = new Map();
Object.keys(objectTypePatterns).forEach(objectType => {
    bracketContentToTypeMap.set(objectType, objectType);
});

