//---------------------------------------------------------------------------------
//server initialization------------------------------------------------------------
//---------------------------------------------------------------------------------

connection.onInitialize((params) => {
    if (params.workspaceFolders) {
        workspaceFolders = params.workspaceFolders;
    } else {
        workspaceFolders = [];
    }
    const capabilities = params.capabilities;
    // Does the client support the `workspace/configuration` request?
    // If not, we fall back using global settings.
    hasConfigurationCapability = !!(capabilities.workspace && !!capabilities.workspace.configuration);
    hasWorkspaceFolderCapability = !!(capabilities.workspace && !!capabilities.workspace.workspaceFolders);
    hasDiagnosticRelatedInformationCapability = !!(capabilities.textDocument &&
        capabilities.textDocument.publishDiagnostics &&
        capabilities.textDocument.publishDiagnostics.relatedInformation);
    const result = {
        capabilities: {
            textDocumentSync: node_1.TextDocumentSyncKind.Incremental,
            // Tell the client that this server supports code completion.
            completionProvider: {
                resolveProvider: true
            },
                signatureHelpProvider: {
                triggerCharacters: ['(', ',', ' '],
                retriggerCharacters: [',', ' ']
            },
            diagnosticProvider: { 
                interFileDependencies: true,
                workspaceDiagnostics: false
            },
            semanticTokensProvider: {
                legend: semanticTokensLegend,
                full: true // Or use delta: true for incremental updates
            },
            definitionProvider: true,
            referencesProvider: true,
            codeLensProvider: {
                resolveProvider: true
            },
            codeActionProvider: {
                resolveProvider: false,
                codeActionKinds: [
                    node_1.CodeActionKind.QuickFix,
                    node_1.CodeActionKind.SourceFixAll,
                ],
            },
        }
    };
//no setup required here.
    if (hasWorkspaceFolderCapability) {
        result.capabilities.workspace = {
            workspaceFolders: {
                supported: true
            }
        };
    }
    if (params.initializationOptions && params.initializationOptions.settings) {
        globalSettings = params.initializationOptions.settings;
        globalSettings = globalSettings.settings;
    }

    return result;
});

//no setup required here.
connection.onInitialized(() => {
    if (hasConfigurationCapability) {
        // Register for all configuration changes.
        connection.client.register(node_1.DidChangeConfigurationNotification.type, undefined);
    }
    if (hasWorkspaceFolderCapability) {
        connection.workspace.onDidChangeWorkspaceFolders(_event => {
            // connection.console.log('Workspace folder change event received.');
            registerWorkspaceFileWatchers();
            rebuildWorkspaceIndex();
            refreshDiagnosticsForOpenAdtDocuments();
            refreshImpactCodeLens();
        });
    }

    if (connection.client && typeof connection.client.register === 'function') {
        registerWorkspaceFileWatchers();
    }

    rebuildWorkspaceIndex();
    
});

