//---------------------------------------------------------------------------------
//connection signature help handling--------------------------------------------------
//---------------------------------------------------------------------------------

connection.onSignatureHelp((params) => {
    const document = documents.get(params.textDocument.uri);
    if (!document) return null;

    const text = document.getText();
    const offset = document.offsetAt(params.position);
    const upto = text.slice(0, offset);

    // Find the nearest "commandName(" before the cursor
    const match = upto.match(/([A-Za-z][A-Za-z0-9_]*)\s*\(([^()]*)$/);
    if (!match) return null;

    const commandName = match[1];
    if (!commandNamesSet.has(commandName)) return null;

    const argsSoFar = match[2];
    const activeParameter = (argsSoFar.match(/,/g) || []).length;

    const validation = commandValidations[commandName];
    const maxInside = validation?.structure?.maxParamsInside ?? 1;
    const paramCount = Math.max(1, maxInside);
    const params2 = Array.from({ length: paramCount }, (_, i) => `param${i + 1}`);

    return {
        signatures: [{
            label: `${commandName}(${params2.join(', ')})`,
            parameters: params2.map((label) => ({ label }))
        }],
        activeSignature: 0,
        activeParameter: Math.min(activeParameter, paramCount - 1)
    };
});



//---------------------------------------------------------------------------------
//connection definition handling (go to definition)--------------------------------
//---------------------------------------------------------------------------------

function escapeRegExp(text) {
    return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function getWordAtPosition(document, position) {
    const lineText = document.getText({
        start: { line: position.line, character: 0 },
        end: { line: position.line, character: Number.MAX_SAFE_INTEGER }
    });
    const wordRegex = /\b[A-Za-z][A-Za-z0-9_-]*\$?\b/g;
    let match;

    while ((match = wordRegex.exec(lineText)) !== null) {
        const start = match.index;
        const end = start + match[0].length;
        if (position.character >= start && position.character <= end) {
            if (isInsideQuotes(lineText, start)) {
                return null;
            }
            return {
                text: match[0],
                start,
                end
            };
        }
    }

    return null;
}

function stripInlineComment(line) {
    return stripValidationComment(line);
}

function lineDeclaresVariable(line, varName) {
    const baseName = extractBaseVariableName(varName);
    const escaped = escapeRegExp(baseName);
    const assignPattern = new RegExp(`\\b${escaped}(?:\\([^)]*\\))?\\s*=`, 'i');
    const setPattern = new RegExp(`\\bset\\s+${escapeRegExp(baseName.replace(/\$$/, ''))}\\b`, 'i');
    //const parenOutputPattern = new RegExp(`\\(\\s*${escaped}\\s*\\)`, 'i');

    return assignPattern.test(line) || setPattern.test(line); //|| parenOutputPattern.test(line);
}

function findDeclarationColumn(line, varName) {
    const baseName = extractBaseVariableName(varName);
    const escaped = escapeRegExp(baseName);
    const patterns = [
        new RegExp(`\\b${escaped}(?:\\([^)]*\\))?\\s*=`, 'i'),
        new RegExp(`\\bset\\s+${escapeRegExp(baseName.replace(/\$$/, ''))}\\b`, 'i'),
        new RegExp(`\\(\\s*${escaped}\\s*\\)`, 'i')
    ];

    for (const pattern of patterns) {
        const match = line.match(pattern);
        if (match) {
            const nameMatch = line.match(new RegExp(`\\b${escaped}`, 'i'));
            if (nameMatch) {
                return nameMatch.index;
            }
            const parenMatch = line.match(new RegExp(`\\(\\s*(${escaped})\\s*\\)`, 'i'));
            if (parenMatch) {
                return parenMatch.index + parenMatch[0].indexOf(parenMatch[1]);
            }
        }
    }

    return 0;
}

function findVariableDeclarationInLines(lines, varName, beforeLine) {
    for (let i = beforeLine-1; i >= 0; i--) {
        const trimmedLine = lines[i].trim();
        if (trimmedLine.startsWith('!')) {
            continue;
        }

        const line = stripInlineComment(lines[i]);
        if (!lineDeclaresVariable(line, varName)) {
            continue;
        }

        return {
            line: i,
            character: findDeclarationColumn(line, varName)
        };
    }

    return null;
}

function collectIncludedFilesBeforeLine(lines, beforeLine) {
    const includes = [];

    for (let i = 0; i <= beforeLine; i++) {
        const trimmedLine = lines[i].trim();
        if (!trimmedLine.startsWith('##included_from')) {
            continue;
        }

        const match = trimmedLine.match(/##included_from\s+(.+?)$/i);
        if (!match) {
            continue;
        }

        includes.push({
            line: i,
            fileName: match[1].trim()
        });
    }

    return includes;
}

function findVariableDeclarationInIncludedFiles(lines, varName, beforeLine) {
    const includes = collectIncludedFilesBeforeLine(lines, beforeLine);

    for (let i = includes.length - 1; i >= 0; i--) {
        const filePath = findFile(includes[i].fileName);
        if (!filePath || !fs.existsSync(filePath) || !fs.lstatSync(filePath).isFile()) {
            continue;
        }

        const includedLines = fs.readFileSync(filePath, 'utf8').split(/\r?\n/);
        const declaration = findVariableDeclarationInLines(includedLines, varName, includedLines.length - 1);
        if (declaration) {
            return {
                uri: URI.file(filePath).toString(),
                line: declaration.line,
                character: declaration.character
            };
        }
    }

    return null;
}

function findVariableDefinition(document, varName, beforeLine) {
    const text = document.getText();
    const lines = text.split(/\r?\n/);

    if (isDebugDocumentText(text)) {
        const assignment = findMostRecentValue(document, beforeLine, varName);
        if (!assignment && varName.endsWith('$')) {
            const withoutSuffix = extractBaseVariableName(varName);
            const fallback = findMostRecentValue(document, beforeLine, withoutSuffix);
            if (fallback) {
                return {
                    uri: document.uri,
                    line: fallback.line,
                    character: findDeclarationColumn(
                        stripInlineComment(lines[fallback.line]),
                        withoutSuffix
                    )
                };
            }
        }
        if (assignment) {
            const lineText = stripInlineComment(lines[assignment.line]);
            return {
                uri: document.uri,
                line: assignment.line,
                character: findDeclarationColumn(lineText, varName)
            };
        }
    }

    const localDeclaration = findVariableDeclarationInLines(lines, varName, beforeLine);
    if (localDeclaration) {
        return {
            uri: document.uri,
            line: localDeclaration.line,
            character: localDeclaration.character
        };
    }

    return findVariableDeclarationInIncludedFiles(lines, varName, beforeLine);
}

function isValidDefinitionTarget(word) {
    const baseName = extractBaseVariableName(word);
    const lookupName = baseName.replace(/\$$/, '');

    if (keywordLabelsSet.has(lookupName) || keywordLabelsSet.has(baseName)) {
        return false;
    }

    if (commandNamesSet.has(lookupName)) {
        return false;
    }

    return true;
}

function applyCasePattern(sourceText, patternText) {
    if (!sourceText) {
        return sourceText;
    }
    if (!patternText) {
        return sourceText;
    }
    if (patternText === patternText.toUpperCase() && patternText !== patternText.toLowerCase()) {
        return sourceText.toUpperCase();
    }
    if (patternText === patternText.toLowerCase()) {
        return sourceText.toLowerCase();
    }
    if (patternText[0] === patternText[0].toUpperCase() &&
        patternText.slice(1) === patternText.slice(1).toLowerCase()) {
        return sourceText.charAt(0).toUpperCase() + sourceText.slice(1).toLowerCase();
    }

    let result = '';
    for (let i = 0; i < sourceText.length; i++) {
        const sourceChar = sourceText[i];
        const patternChar = patternText[i];
        if (patternChar === undefined) {
            result += sourceChar;
            continue;
        }
        if (patternChar === patternChar.toUpperCase() && patternChar !== patternChar.toLowerCase()) {
            result += sourceChar.toUpperCase();
        } else if (patternChar === patternChar.toLowerCase()) {
            result += sourceChar.toLowerCase();
        } else {
            result += sourceChar;
        }
    }
    return result;
}

function stripLocalSlotPrefixFromMatchedText(oldName, matchedText) {
    const oldPrefix = getLocalSlotPrefix(oldName);
    if (!oldPrefix || matchedText.length <= oldPrefix.length) {
        return matchedText;
    }
    const prefixPart = matchedText.slice(0, oldPrefix.length);
    if (prefixPart.toLowerCase() === oldPrefix.toLowerCase()) {
        return matchedText.slice(oldPrefix.length);
    }
    return matchedText;
}

function buildCasePreservingLocalSlotRenameText(pair, matchedText) {
    const slotPrefix = getLocalSlotPrefix(pair.newName);
    const canonicalBase = getLocalSlotBaseName(pair.newName) ||
        (isLocalSlotVariableName(pair.oldName)
            ? getLocalSlotBaseName(pair.oldName)
            : extractBaseVariableName(pair.oldName));
    const matchedBase = stripLocalSlotPrefixFromMatchedText(pair.oldName, matchedText);
    const casedBase = applyCasePattern(canonicalBase, matchedBase);
    return `${slotPrefix}${casedBase}`;
}

function buildVariableReferenceRegex(varName) {
    const baseName = extractBaseVariableName(varName);
    const escaped = escapeRegExp(baseName);

    if (baseName.endsWith('$')) {
        return new RegExp(`\\b${escaped}\\b`, 'gi');
    }

    return new RegExp(`\\b${escaped}\\b(?!\\$)`, 'gi');
}

function findVariableReferencesInLines(lines, varName, uri) {
    const references = [];
    const regex = buildVariableReferenceRegex(varName);
    const expectedName = extractBaseVariableName(varName);

    for (let i = 0; i < lines.length; i++) {
        const trimmedLine = lines[i].trim();
        if (trimmedLine.startsWith('!')) {
            continue;
        }

        const codeLine = stripInlineComment(lines[i]);
        regex.lastIndex = 0;
        let match;

        while ((match = regex.exec(codeLine)) !== null) {
            if (isInsideQuotes(codeLine, match.index)) {
                continue;
            }

            const matchedText = match[0];
            if (matchedText.toLowerCase() !== expectedName.toLowerCase()) {
                continue;
            }

            references.push({
                uri,
                matchedText,
                range: {
                    start: { line: i, character: match.index },
                    end: { line: i, character: match.index + matchedText.length }
                }
            });
        }
    }

    return references;
}

function collectAllIncludedFiles(lines) {
    return collectIncludedFilesBeforeLine(lines, lines.length - 1);
}

function findAllVariableReferences(document, varName, cursorLine, includeDeclaration) {
    const references = [];
    const filesToSearch = new Map();
    const lines = document.getText().split(/\r?\n/);

    filesToSearch.set(document.uri, lines);

    const definition = findVariableDefinition(document, varName, cursorLine);
    if (definition && definition.uri !== document.uri) {
        try {
            const definitionPath = URI.parse(definition.uri).fsPath;
            if (fs.existsSync(definitionPath)) {
                filesToSearch.set(
                    definition.uri,
                    fs.readFileSync(definitionPath, 'utf8').split(/\r?\n/)
                );
            }
        } catch (error) {
            // Ignore unreadable definition files.
        }
    }

    for (const include of collectAllIncludedFiles(lines)) {
        const filePath = findFile(include.fileName);
        if (!filePath || !fs.existsSync(filePath) || !fs.lstatSync(filePath).isFile()) {
            continue;
        }

        const uri = URI.file(filePath).toString();
        if (!filesToSearch.has(uri)) {
            filesToSearch.set(uri, fs.readFileSync(filePath, 'utf8').split(/\r?\n/));
        }
    }

    for (const [uri, fileLines] of filesToSearch) {
        references.push(...findVariableReferencesInLines(fileLines, varName, uri));
    }

    if (!includeDeclaration && definition) {
        const nameLength = extractBaseVariableName(varName).length;
        return references.filter((reference) => {
            if (reference.uri !== definition.uri) {
                return true;
            }

            const sameLine = reference.range.start.line === definition.line;
            const sameColumn = reference.range.start.character === definition.character;
            const sameSpan = reference.range.end.character === definition.character + nameLength;
            return !(sameLine && sameColumn && sameSpan);
        });
    }

    return references;
}

connection.onDefinition((params) => {
    const document = documents.get(params.textDocument.uri);
    if (!document) {
        return null;
    }

    const word = getWordAtPosition(document, params.position);
    if (!word || !isValidDefinitionTarget(word.text)) {
        return null;
    }

    const definition = findVariableDefinition(document, word.text, params.position.line);
    if (!definition) {
        return null;
    }

    const nameLength = extractBaseVariableName(word.text).length;

    return {
        uri: definition.uri,
        range: {
            start: { line: definition.line, character: definition.character },
            end: { line: definition.line, character: definition.character + nameLength }
        }
    };
});

connection.onReferences((params) => {
    const document = documents.get(params.textDocument.uri);
    if (!document) {
        return [];
    }

    const word = getWordAtPosition(document, params.position);
    if (!word || !isValidDefinitionTarget(word.text)) {
        return [];
    }

    const includeDeclaration = params.context ? params.context.includeDeclaration : true;
    return findAllVariableReferences(
        document,
        word.text,
        params.position.line,
        includeDeclaration
    );
});

connection.onCodeLens(async (params) => {
    if (!isImpactAnalysisEnabled()) {
        return [];
    }

    const filePath = uriToFsPath(params.textDocument.uri);
    if (!shouldIndexAdtFile(filePath)) {
        return [];
    }

    if (!shouldShowImpactCodeLens(filePath)) {
        return [];
    }

    return [
        node_1.CodeLens.create(
            node_1.Range.create(0, 0, 0, 1),
            { kind: 'impact', uri: params.textDocument.uri }
        )
    ];
});

connection.onCodeLensResolve(async (codeLens) => {
    if (!codeLens.data || codeLens.data.kind !== 'impact' || !codeLens.data.uri) {
        return codeLens;
    }

    const filePath = uriToFsPath(codeLens.data.uri);
    const analysis = analyzeFileImpact(filePath);
    const incomingTotal = analysis.incoming.calls + analysis.incoming.includes;
    const scopeCount = analysis.scopes.length;

    codeLens.command = {
        title: `Impact: ${analysis.incoming.calls} calls, ${analysis.incoming.includes} includes | Blast radius: ${analysis.totalBlastRadiusFiles} instances in ${scopeCount} program(s)`,
        command: 'vertexadt.showImpactAnalysis',
        arguments: [{
            uri: codeLens.data.uri,
            analysis,
        }],
    };

    if (incomingTotal === 0) {
        codeLens.command = undefined;
    }

    return codeLens;
});

