//this starts the checking of the document, is run when making any change to document, 
//is run after ondidchangecontent
connection.languages.diagnostics.on(async (params) => {
    console.time('complete run time');
    console.time(`Diagnostics Request Setup for ${params.textDocument.uri}`);


    const document = documents.get(params.textDocument.uri);
    if (document !== undefined) {
        const currentText = document.getText();
        //check if document is a debug file, if so, don't validate anything.
        //check if string "START OF DEBUG in FILE" is in the document.
        if (isValidationExcludedDocumentText(currentText)) {
            console.timeEnd(`Diagnostics Request Setup for ${params.textDocument.uri}`);
            //skip validation
            return {
                kind: node_1.DocumentDiagnosticReportKind.Full,
                items: []
            };
        }


        const previousText = previousDocumentVersions.get(document.uri) || "";

        console.time(`Diagnostics Diff Detection for ${document.uri}`);
        let result = findTextDifference(previousText, currentText);

        previousDocumentVersions.set(document.uri, currentText);
        console.timeEnd(`Diagnostics Diff Detection for ${document.uri}`);
        console.timeEnd(`Diagnostics Request Setup for ${params.textDocument.uri}`);

        const cachedItems = getCachedDiagnostics(document);
        if (cachedItems !== null) {
            console.timeEnd('complete run time');
            return {
                kind: node_1.DocumentDiagnosticReportKind.Full,
                items: cachedItems,
            };
        }

        if (previousText.length === 0 || previousText === currentText || result.removed.includes('\n')) {
            const items = await validateTextDocumentExclusive(document);
            setCachedDiagnostics(document, items);
            if (connection.languages && connection.languages.semanticTokens && typeof connection.languages.semanticTokens.refresh === 'function') {
                connection.languages.semanticTokens.refresh();
            }
            return {
                //check the whole document for errors
                kind: node_1.DocumentDiagnosticReportKind.Full,
                items,
            };
        }
        else {
            //get the changed line text string.
            let changedLine = result.newLine;
            let changedLineIndex = result.lineNumber;
            const items = await validateTextDocumentExclusive(document);
            setCachedDiagnostics(document, items);
            if (connection.languages && connection.languages.semanticTokens && typeof connection.languages.semanticTokens.refresh === 'function') {
                connection.languages.semanticTokens.refresh();
            }
            return {
                //validate only the changed line. return all errors.
                kind: node_1.DocumentDiagnosticReportKind.Full,
                //items: await validateTextDocument(document, changedLineIndex),
                items,
        }};
    }
    else {
        console.timeEnd(`Diagnostics Request Setup for ${params.textDocument.uri}`);
        // We don't know the document. We can either try to read it from disk
        // or we don't report problems for it. (no problems reported currently)
        return {
            kind: node_1.DocumentDiagnosticReportKind.Full,
            items: []
        };
    }
});

