// Cache the settings of all open documents
// this is run when settings have been modified and during initialization.
connection.onDidChangeConfiguration(change => {
    if (hasConfigurationCapability) {
        // Reset all cached document settings
        documentSettings.clear();
    }
    else {
        globalSettings = (change.settings.languageServerExample || defaultSettings);
    }
    
    // Update strict mode setting if provided
    if (change.settings && change.settings.vertexAdt && change.settings.vertexAdt.strictMode.enabled !== undefined) {
        strictModeEnabled = change.settings.vertexAdt.strictMode;
    }

    // Refresh the configuration of all open documents
    documents.all().forEach((document) => {
        void validateTextDocumentExclusive(document);
    });
});

//not used.
connection.onDidChangeWatchedFiles(change => {
    if (!change || !change.changes) {
        return;
    }
    for (let i = 0; i < change.changes.length; i++) {
        const watchedChange = change.changes[i];
        const filePath = uriToFsPath(watchedChange.uri);
        if (!filePath) {
            continue;
        }
        if (!shouldIndexAdtFile(filePath)) {
            if (watchedChange.type === node_1.FileChangeType.Deleted) {
                workspaceDeclarationIndex.delete(normalizeFsPath(filePath));
            }
            continue;
        }
        if (watchedChange.type === node_1.FileChangeType.Deleted) {
            workspaceDeclarationIndex.delete(normalizeFsPath(filePath));
        }
        else {
            updateIndexForFile(filePath, undefined, true);
        }
    }
    scheduleConnectedDiagnosticsRefresh(change.changes[0]?.uri, { force: true });
});

