// Listen for settings updates
connection.onNotification('custom/updateSettings', (settings) => {
    const previousStrictMode = globalSettings?.strictMode;
    const previousImpactEnabled = globalSettings?.impactAnalysis?.enabled;
    const previousNoteUnusedVariables = globalSettings?.noteUnusedVariables;
    const previousCallParamValidation = globalSettings?.calls?.validateParameterCount;
    const previousLocalsSettings = JSON.stringify(globalSettings?.locals || {});
    const previousWarnUnclosedResources = globalSettings?.diagnostics?.warnUnclosedResources;
    globalSettings = { ...globalSettings, ...settings };
    if (previousStrictMode !== globalSettings.strictMode) {
        refreshDiagnosticsForOpenAdtDocuments();
    }
    if (previousImpactEnabled !== globalSettings?.impactAnalysis?.enabled) {
        refreshImpactCodeLens();
    }
    if (previousNoteUnusedVariables !== globalSettings?.noteUnusedVariables) {
        refreshDiagnosticsForOpenAdtDocuments();
    }
    if (previousCallParamValidation !== globalSettings?.calls?.validateParameterCount) {
        refreshDiagnosticsForOpenAdtDocuments();
    }
    if (previousLocalsSettings !== JSON.stringify(globalSettings?.locals || {})) {
        refreshDiagnosticsForOpenAdtDocuments();
    }
    if (previousWarnUnclosedResources !== globalSettings?.diagnostics?.warnUnclosedResources) {
        refreshDiagnosticsForOpenAdtDocuments();
    }
});


