//returns real path from $DIR_ string or uri path.
connection.onRequest('custom/getIncludeDirectories', (params) => {
    let initialPath = params.initialPath;
    let firstpart;
    let firstpart2;
    let workspaceRoot;

    //get workspaceroot
    if (workspaceFolders && workspaceFolders.length > 1) {
        workspaceRoot = workspaceFolders[0].uri;
        workspaceRoot = workspaceRoot.replace('file:///', '');
        workspaceRoot = workspaceRoot.replace(/\//g, '/');
        workspaceRoot = workspaceRoot.replace('%3A', ':');
        //remove the last directory of the path
        workspaceRoot = workspaceRoot.substring(0, workspaceRoot.lastIndexOf('/'));
        //add / at end of path
        //workspaceRoot = workspaceRoot + '/';
    } else if (workspaceFolders && workspaceFolders.length === 1) {
        workspaceRoot = workspaceFolders[0].uri;
        workspaceRoot = workspaceRoot.replace('file:///', '');
        workspaceRoot = workspaceRoot.replace(/\//g, '/');
        workspaceRoot = workspaceRoot.replace('%3A', ':');
        //remove the last directory of the path
        workspaceRoot = workspaceRoot.substring(0, workspaceRoot.lastIndexOf('/'));
        //add / at end of path
        //workspaceRoot = workspaceRoot + '/';
    }

    // check if initialpath is empty.
    if (initialPath === "") {
        //if so return array of $DIR_ strings.
        //get all keywords which label starts with $
        let dollarkeywords = [];
        //loop through each label in keywords array.
        for (let i = 0; i < keywords.length; i++) {
            //check if label starts with $
            if (keywords[i].label.startsWith('$')) {
                //if so, push it to the dollarkeywords array.
                dollarkeywords.push(keywords[i].label);
            }
        }
        //return the keywords
        return dollarkeywords;
    }

    
    // check if initialpath contains $
    if (initialPath.includes('$')) {
        //take the string and replace it with function.
        try {
            firstpart = initialPath.split('/')[0];
        } catch {
            firstpart = initialPath;
        }
        firstpart2 = convertVertexPathToString(firstpart);
        //combine back the string
        initialPath = initialPath.replace(firstpart, firstpart2);
    }

    try {
        // Determine the base directory from the initialPath
        let basePath;
        let relativePath = '';
        // Default case - search in both system and custom dirs
        basePath = searchInCustomAndSystem(workspaceRoot, initialPath);
        //loop through basepath removing the ending / from each string.
        for (let i = 0; i < basePath.length; i++) {
            if (basePath[i].endsWith('/')) {
                basePath[i] = basePath[i].slice(0, -1);
            }   
        }

        // Get directory contents for the path
        return basePath;
    } catch (error) {
        console.error("Error retrieving directory contents:", error);
        return [];
    }
});

function joinVertexPath(directory, name) {
    const base = String(directory || '').replace(/\\/g, '/').replace(/\/$/, '');
    const leaf = String(name || '').replace(/\\/g, '/');
    if (!base) {
        return leaf;
    }
    if (!leaf) {
        return base;
    }
    return `${base}/${leaf}`;
}

function vertexRelativePathIsDirectory(inputPath) {
    const workspaceRoot = getWorkspaceRootPath();
    if (!workspaceRoot || !inputPath) {
        return false;
    }

    let relative = stripPathQuotes(inputPath).replace(/\\/g, '/').trim();
    if (!relative) {
        return false;
    }
    if (relative.startsWith('$')) {
        const parts = relative.split('/');
        const converted = convertVertexPathToString(parts[0]);
        if (converted) {
            parts[0] = converted;
            relative = parts.join('/');
        }
    }

    const customname = getCustomFolderNameFromWorkspace();
    const candidates = [
        path.join(workspaceRoot, relative),
        path.join(workspaceRoot, customname, relative),
        path.join(workspaceRoot, 'system', relative)
    ];
    for (let i = 0; i < candidates.length; i++) {
        try {
            if (fs.existsSync(candidates[i]) && fs.lstatSync(candidates[i]).isDirectory()) {
                return true;
            }
        } catch (_error) {
            // Skip unreadable candidates.
        }
    }
    return false;
}

function getTargetSectionNamesForVertexPath(vertexPath) {
    const resolved = resolveVertexFilePath(vertexPath);
    if (!resolved) {
        return [];
    }
    const text = loadLinkedFileText(resolved);
    if (!text) {
        return [];
    }
    return targetSectionSupport.listUniqueTargetSectionNames(text);
}

function listIncludeDirectoryEntries(initialPath) {
    const workspaceRoot = getWorkspaceRootPath();
    if (!workspaceRoot) {
        return [];
    }

    let query = String(initialPath || '');
    if (query.includes('$')) {
        let firstpart;
        try {
            firstpart = query.split('/')[0];
        } catch (_error) {
            firstpart = query;
        }
        const converted = convertVertexPathToString(firstpart);
        if (converted) {
            query = query.replace(firstpart, converted);
        }
    }

    try {
        return searchInCustomAndSystem(workspaceRoot, query);
    } catch (_error) {
        return [];
    }
}

function collectDollarDirectoryKeywords() {
    const dollarkeywords = [];
    for (let i = 0; i < keywords.length; i++) {
        if (keywords[i].label.startsWith('$')) {
            dollarkeywords.push(keywords[i].label);
        }
    }
    return dollarkeywords;
}

connection.onRequest('custom/getIncludeCallCompletion', (params) => {
    const lineText = params && params.lineText ? String(params.lineText) : '';
    const cursorCharacter = params && typeof params.cursorCharacter === 'number'
        ? params.cursorCharacter
        : 0;

    const analysis = targetSectionSupport.analyzeIncludeCallCompletion({
        lineText,
        cursorCharacter,
        triggerKind: params && params.triggerKind,
        triggerCharacter: params && params.triggerCharacter,
        pathStatus: (filePath) => ({
            isFile: !!resolveVertexFilePath(filePath),
            isDirectory: vertexRelativePathIsDirectory(filePath)
        }),
        getSectionNames: getTargetSectionNamesForVertexPath
    });

    if (!analysis || analysis.mode === 'none') {
        return { mode: 'none' };
    }

    if (analysis.mode === 'sections') {
        return {
            mode: 'sections',
            sections: analysis.sections || [],
            insertLeadingSpace: !!analysis.insertLeadingSpace,
            replaceStart: analysis.replaceStart,
            replaceEnd: analysis.replaceEnd
        };
    }

    const filePath = analysis.filePath || '';
    if (!filePath) {
        return {
            mode: 'paths',
            dirKeywords: collectDollarDirectoryKeywords(),
            entries: []
        };
    }

    const listing = listIncludeDirectoryEntries(filePath);
    const attachSections = analysis.directive !== 'included_from';
    const entries = [];
    for (let i = 0; i < listing.length; i++) {
        const raw = listing[i];
        const isDirectory = raw.endsWith('/');
        const name = isDirectory ? raw : raw;
        const entry = {
            name,
            isDirectory,
            sections: []
        };
        if (!isDirectory && attachSections) {
            const childPath = joinVertexPath(filePath, name);
            entry.sections = getTargetSectionNamesForVertexPath(childPath);
        }
        entries.push(entry);
    }

    return {
        mode: 'paths',
        entries
    };
});

// Resolve a vertex include/call path to an existing file on disk.
connection.onRequest('custom/resolveIncludePath', (params) => {
    try {
        const inputPath = (params && params.filePath ? String(params.filePath) : '').trim();
        if (!inputPath || !workspaceFolders || workspaceFolders.length === 0) {
            return null;
        }

        const stripQuotes = (value) => {
            const trimmed = value.trim();
            if ((trimmed.startsWith('"') && trimmed.endsWith('"'))) {
                return trimmed.slice(1, -1);
            }
            return trimmed;
        };

        const normalizeWorkspaceUri = (uriText) => {
            let root = uriText.replace('file:///', '');
            root = decodeURIComponent(root);
            root = root.replace(/\//g, '/');
            return root;
        };

        const getWorkspaceRoot = () => {
            let root = normalizeWorkspaceUri(workspaceFolders[0].uri);
            if (workspaceFolders.length > 1) {
                root = root.substring(0, root.lastIndexOf('/'));
            }
            return root;
        };

        const getCustomFolderName = () => {
            let customname = 'custom';
            for (let i = 0; i < workspaceFolders.length; i++) {
                const workspaceFolder = workspaceFolders[i].uri;
                if (workspaceFolder.includes('custom')) {
                    customname = workspaceFolder.split('/').pop();
                    customname = decodeURIComponent(customname);
                    break;
                }
            }
            return customname;
        };

        let filePath = stripQuotes(inputPath).replace(/\\/g, '/');
        if (!filePath) {
            return null;
        }

        // Convert the first $DIR_* segment exactly like other completion handlers do.
        if (filePath.startsWith('$')) {
            const parts = filePath.split('/');
            const converted = convertVertexPathToString(parts[0]);
            if (!converted) {
                return null;
            }
            parts[0] = converted;
            filePath = parts.join('/');
        }

        const workspaceRoot = getWorkspaceRoot();
        const customname = getCustomFolderName();

        const candidatePaths = [];
        if (path.isAbsolute(filePath)) {
            candidatePaths.push(path.normalize(filePath));
        }

        candidatePaths.push(path.normalize(path.join(workspaceRoot, filePath)));
        candidatePaths.push(path.normalize(path.join(workspaceRoot, customname, filePath)));
        candidatePaths.push(path.normalize(path.join(workspaceRoot, 'system', filePath)));

        // Also use the existing recursive locator for include/call style relative paths.
        const recursiveMatch = findFileRecursive(workspaceRoot, filePath, customname);
        if (recursiveMatch) {
            candidatePaths.push(path.normalize(recursiveMatch));
        }

        for (let i = 0; i < candidatePaths.length; i++) {
            const candidate = candidatePaths[i];
            if (candidate && fs.existsSync(candidate) && fs.lstatSync(candidate).isFile()) {
                return candidate;
            }
        }

        return null;
    } catch (error) {
        console.error('Error resolving include path:', error);
        return null;
    }
});

function resolveCallTargetFile(filePath) {
    const cleanedPath = targetSectionSupport.lookupPathFromCallArgument(filePath);
    if (!cleanedPath) {
        return null;
    }
    const resolved = resolveVertexFilePath(cleanedPath);
    if (resolved) {
        return resolved;
    }
    let lookupPath = cleanedPath;
    if (lookupPath.includes('$')) {
        const firstpart = lookupPath.split('/')[0];
        const converted = convertVertexPathToString(firstpart);
        if (converted) {
            lookupPath = lookupPath.replace(firstpart, converted);
        }
    }
    return findFile(lookupPath);
}

//returns input parameters for ret$=call(...) usage.
connection.onRequest('custom/getCallParameters', async (params) => {
    let { filePath } = params;
    
    try {
        const parsedPath = targetSectionSupport.parseIncludeCallPathAndSection(filePath, '');
        const resolvedPath = resolveCallTargetFile(filePath);
        
        if (!resolvedPath) {
            return [];
        }
        
        // Read the file content
        
        const fileContent = fs.readFileSync(resolvedPath, 'utf8');
        
        // Parse the file to extract parameter information
        const parameters = extractFunctionParameters(
            fileContent,
            params.targetSection || parsedPath.targetSection
        );
        
        return parameters;
    } catch (error) {
        console.error(`Error getting parameters from file ${filePath}:`, error);
        return [];
    }
});

connection.onCodeAction(async (params) => {
    const actions = [];
    const document = documents.get(params.textDocument.uri);
    if (!document) {
        return actions;
    }

    const contextDiagnostics = params.context?.diagnostics || [];
    const onlyKinds = params.context?.only || [];
    const wantsQuickFix = onlyKinds.length === 0 ||
        onlyKinds.some((kind) => kind === node_1.CodeActionKind.QuickFix || kind === node_1.CodeActionKind.QuickFix.value);

    if (isCallParamValidationEnabled()) {
        const missingDiagnostics = contextDiagnostics.filter((diag) => diag.code === 'vertexadt/missing-call-params');
        const wantsFixAll = onlyKinds.length === 0 ||
            onlyKinds.some((kind) => kind === node_1.CodeActionKind.SourceFixAll || kind === node_1.CodeActionKind.SourceFixAll.value);

        if (wantsQuickFix) {
            for (let i = 0; i < missingDiagnostics.length; i++) {
                const diag = missingDiagnostics[i];
                const data = diag.data || {};
                const missingCount = data.missingCount || 0;
                if (missingCount <= 0 || typeof data.insertOffset !== 'number' || typeof data.line !== 'number') {
                    continue;
                }
                const action = node_1.CodeAction.create(
                    `Add ${missingCount} missing call parameter(s) as ""`,
                    node_1.CodeActionKind.QuickFix
                );
                action.diagnostics = [diag];
                action.edit = {
                    changes: {
                        [params.textDocument.uri]: [{
                            range: {
                                start: { line: data.line, character: data.insertOffset },
                                end: { line: data.line, character: data.insertOffset },
                            },
                            newText: buildMissingCallParamInsertText(missingCount),
                        }],
                    },
                };
                actions.push(action);
            }
        }

        if (wantsFixAll && missingDiagnostics.length > 0) {
            const editEntries = [];
            for (let i = 0; i < missingDiagnostics.length; i++) {
                const data = missingDiagnostics[i].data || {};
                if ((data.missingCount || 0) <= 0 || typeof data.insertOffset !== 'number' || typeof data.line !== 'number') {
                    continue;
                }
                editEntries.push({
                    uri: params.textDocument.uri,
                    line: data.line,
                    character: data.insertOffset,
                    newText: buildMissingCallParamInsertText(data.missingCount),
                });
            }
            editEntries.sort((a, b) => {
                if (a.line !== b.line) {
                    return b.line - a.line;
                }
                return b.character - a.character;
            });
            if (editEntries.length > 0) {
                const action = node_1.CodeAction.create(
                    `Add missing call parameters as "" in file (${editEntries.length})`,
                    node_1.CodeActionKind.SourceFixAll
                );
                action.edit = buildWorkspaceEditFromMissingCallParamEdits(editEntries);
                actions.push(action);
            }
        }
    }

    if (wantsQuickFix) {
        const unclosedDiagnostics = contextDiagnostics.filter((diag) =>
            diag.code === unclosedResources.UNCLOSED_RESOURCE_CODE ||
            diag.code === unclosedResources.UNCLOSED_ALREADY_OPEN_CODE
        );
        for (let i = 0; i < unclosedDiagnostics.length; i++) {
            const diag = unclosedDiagnostics[i];
            const data = diag.data || {};
            const lineIndex = typeof data.line === 'number' ? data.line : diag.range?.start?.line;
            if (typeof lineIndex !== 'number') {
                continue;
            }
            const lines = document.getText().split(/\r?\n/);
            const lineText = lines[lineIndex] || '';
            const insertion = unclosedResources.buildIgnoreCloseInsertion(lineText);
            if (!insertion) {
                continue;
            }
            const action = node_1.CodeAction.create(
                'Ignore missing close (;!IGNORE CLOSE)',
                node_1.CodeActionKind.QuickFix
            );
            action.diagnostics = [diag];
            action.edit = {
                changes: {
                    [params.textDocument.uri]: [{
                        range: {
                            start: { line: lineIndex, character: insertion.character },
                            end: { line: lineIndex, character: insertion.character },
                        },
                        newText: insertion.newText,
                    }],
                },
            };
            actions.push(action);
        }
    }

    if (wantsQuickFix) {
        const namingDiagnostics = contextDiagnostics.filter((diag) => diag.code === 'vertexadt/callee-local-naming');
        for (let i = 0; i < namingDiagnostics.length; i++) {
            const diag = namingDiagnostics[i];
            const data = diag.data || {};
            if (!data.varName || !data.newName) {
                continue;
            }
            const lines = document.getText().split(/\r?\n/);
            const renameEdits = buildFileWideVariableRenameEdits(
                params.textDocument.uri,
                lines,
                [{ oldName: data.varName, newName: data.newName }]
            );
            if (renameEdits.length === 0) {
                continue;
            }
            const action = node_1.CodeAction.create(
                `Rename ${data.varName} to ${data.newName} in file`,
                node_1.CodeActionKind.QuickFix
            );
            action.diagnostics = [diag];
            action.edit = buildWorkspaceEditFromCallParamEdits(renameEdits);
            actions.push(action);
        }
    }

    return actions;
});

connection.onRequest('custom/fixMissingCallParameters', async () => {
    if (!isCallParamValidationEnabled()) {
        return { changes: {}, fixedCount: 0 };
    }

    const filesToScan = new Map();
    workspaceDeclarationIndex.forEach((_entry, normalizedPath) => {
        filesToScan.set(normalizedPath, null);
    });
    for (const document of documents.all()) {
        const normalizedPath = normalizeFsPath(uriToFsPath(document.uri));
        if (normalizedPath) {
            filesToScan.set(normalizedPath, document.getText());
        }
    }

    const editEntries = [];
    filesToScan.forEach((content, normalizedPath) => {
        const fileContent = content !== null ? content : loadLinkedFileText(normalizedPath);
        if (!fileContent) {
            return;
        }
        const uri = fsPathToUri(normalizedPath);
        const fileEdits = buildMissingCallParamWorkspaceEditsForContent(uri, fileContent);
        for (let i = 0; i < fileEdits.length; i++) {
            editEntries.push(fileEdits[i]);
        }
    });

    return {
        changes: buildWorkspaceEditFromMissingCallParamEdits(editEntries).changes,
        fixedCount: editEntries.length,
    };
});

connection.onRequest('custom/assignLocalSlotNames', async (params) => {
    const targetUri = params?.uri;
    if (!targetUri) {
        return { changes: {}, assignedCount: 0, error: 'No target file specified' };
    }

    const filePath = uriToFsPath(targetUri);
    if (!filePath) {
        return { changes: {}, assignedCount: 0, error: 'Invalid target file URI' };
    }

    rebuildWorkspaceIndex();
    const document = documents.get(targetUri);
    const fileContent = document ? document.getText() : loadLinkedFileText(filePath);
    if (!fileContent) {
        return { changes: {}, assignedCount: 0, error: 'Could not read target file' };
    }

    const uri = fsPathToUri(filePath);
    const editEntries = buildAssignLocalSlotNameEdits(uri, fileContent, filePath);
    return {
        changes: buildWorkspaceEditFromCallParamEdits(editEntries).changes,
        assignedCount: editEntries.length,
    };
});

//returns return values from ret$=call(...) usage.
connection.onRequest('custom/getCallReturnValues', async (params) => {
    let { filePath } = params;
    
    try {
        const resolvedPath = resolveCallTargetFile(filePath);
        
        if (!resolvedPath) {
            return [];
        }
        
        // Read the file content
        const fileContent = fs.readFileSync(resolvedPath, 'utf8');
        
        // Parse the file to extract return string format
        return extractReturnValues(fileContent);
    } catch (error) {
        console.error(`Error getting return values from file ${filePath}:`, error);
        return [];
    }
});

connection.onRequest('custom/getVariableObjectType', async (params) => {
    const { uri, variableName, line } = params;
    if (!variableName || typeof line !== 'number') {
        return 'generic';
    }

    const document = documents.get(uri);
    if (!document) {
        return 'generic';
    }

    await extractVariables(document.getText(), true, true);
    variableTypes.length = 0;
    const typeLines = document.getText().split(/\r?\n/);
    variableTypeCollection(typeLines);
    const fileSections = parseFileSections(typeLines);

    const baseVariableName = extractBaseVariableName(variableName);
    const type = getCurrentVariableType(baseVariableName, line, fileSections);
    return type || 'generic';
});

function listMacroLibraryXmlFiles(libraryPath) {
    try {
        return fs.readdirSync(libraryPath, { withFileTypes: true })
            .filter(dirent => dirent.isFile() && dirent.name.startsWith('d_') && dirent.name.toLowerCase().endsWith('.xml'))
            .map(dirent => dirent.name);
    } catch (error) {
        console.error(`Error reading XML exports in ${libraryPath}: ${error}`);
        return [];
    }
}

function isPrimaryMacroDatabaseFile(fileName, allDatabaseFiles) {
    if (!/[cl]$/i.test(fileName)) {
        return true;
    }

    return !allDatabaseFiles.has(fileName.slice(0, -1));
}

function ensureMacroLibraryXmlExports(libraryPath) {
    if (!fs.existsSync(libraryPath)) {
        return [];
    }

    let databaseFiles = [];
    try {
        const candidateDatabaseFiles = fs.readdirSync(libraryPath, { withFileTypes: true })
            .filter(dirent => dirent.isFile() && dirent.name.startsWith('d_') && path.extname(dirent.name) === '')
            .map(dirent => dirent.name);

        const candidateDatabaseFileSet = new Set(candidateDatabaseFiles);
        databaseFiles = candidateDatabaseFiles.filter(fileName => isPrimaryMacroDatabaseFile(fileName, candidateDatabaseFileSet));
    } catch (error) {
        console.error(`Error reading macro library directory ${libraryPath}: ${error}`);
        return [];
    }

    if (!fs.existsSync(vertexDbaseConverterPath)) {
        console.error(`Vertex database converter not found at ${vertexDbaseConverterPath}`);
        return listMacroLibraryXmlFiles(libraryPath);
    }

    for (const databaseFileName of databaseFiles) {
        const databaseFilePath = path.join(libraryPath, databaseFileName);
        const xmlFilePath = `${databaseFilePath}.xml`;

        try {
            const needsExport = !fs.existsSync(xmlFilePath)
                || fs.statSync(databaseFilePath).mtimeMs > fs.statSync(xmlFilePath).mtimeMs;

            if (!needsExport) {
                continue;
            }

            execFileSync(vertexDbaseConverterPath, [
                databaseFilePath,
                '--all',
                '--xml',
                '--export', xmlFilePath
            ], {
                cwd: path.dirname(vertexDbaseConverterPath),
                encoding: 'utf8',
                windowsHide: true
            });
        } catch (error) {
            const details = error.stderr || error.stdout || error.message;
            console.error(`Error exporting macro XML for ${databaseFilePath}: ${details}`);
        }
    }

    return listMacroLibraryXmlFiles(libraryPath);
}

connection.onRequest('custom/getMacroLibraries', () => {
    if (!workspaceFolders || workspaceFolders.length === 0) {
        return [];
    }

    // Get workspace folders from initialization
    let customname = "custom";
    if (workspaceFolders) {
        //loop through each workspaces folder.
        for (let i = 0; i < workspaceFolders.length; i++) {
            let workspaceFolder = workspaceFolders[i].uri;
            //check if the folder name contains "custom"
            if (workspaceFolder.includes("custom")) {
                //get the full name of that folder.
                customname = workspaceFolder.split('/').pop();
                //replace the %3A with : and replace the / with \
                customname = customname.replace(/\//g, '\\');
                customname = customname.replace('%3A', ':');
    }}}
    
    const libraries = [];
    
    // Try to find the custom/complibs folder in any workspace folder
    for (const folder of workspaceFolders) {
        try {
            if (folder.uri.includes(customname)) {
                const folderPath = URI.parse(folder.uri).fsPath;
                const complibsPath = path.join(folderPath, 'complibs');
                
                if (fs.existsSync(complibsPath)) {
                    // Read directories
                    const dirs = fs.readdirSync(complibsPath, { withFileTypes: true })
                        .filter(dirent => dirent.isDirectory())
                        .map(dirent => dirent.name);

                    // Check each directory for d_*.xml files
                    for (const dir of dirs) {
                        const dirPath = path.join(complibsPath, dir);
                        const files = ensureMacroLibraryXmlExports(dirPath);

                        // Check if there's at least one d_*.xml file
                        if (files.length > 0) {
                            let outdir = dir.toUpperCase()
                            libraries.push(outdir);
                        }
                    }

                    // Found the folder and processed it, no need to check other workspaces
                    break;
                }}
        } catch (error) {
            console.error(`Error scanning for macro libraries: ${error}`);
        }
    }
    
    return libraries;
});

