connection.onRequest('custom/getMacroCodes', (params) => {
    if (!params.library) {
        return [];
    }
    if (!workspaceFolders || workspaceFolders.length === 0) {
        return [];
    }

    // Get workspace folders from initialization
    let customname = "custom";
    if (workspaceFolders) {
        //loop through each workspaces folder.
        for (let i = 0; i < workspaceFolders.length; i++) {
            let workspaceFolder = workspaceFolders[i].uri;
            //check if the folder name contains "custom"
            if (workspaceFolder.includes("custom")) {
                //get the full name of that folder.
                customname = workspaceFolder.split('/').pop();
                //replace the %3A with : and replace the / with \
                customname = customname.replace(/\//g, '\\');
                customname = customname.replace('%3A', ':');
    }}}



    for (const folder of workspaceFolders) {
        try {
            if (folder.uri.includes(customname)) {
                const folderPath = URI.parse(folder.uri).fsPath;
                const macropath = path.join(folderPath, 'complibs');
                const libraryPath = path.join(macropath, params.library);
                ensureMacroLibraryXmlExports(libraryPath);
                //make xml file path.
                const xmlFilePath = path.join(libraryPath, "d_"+ params.library + ".xml");
                //read the xml file.
                let xmlContent;
                try {
                    xmlContent = fs.readFileSync(xmlFilePath, 'utf8');
                } catch (error) {
                    xmlContent = fs.readFileSync(path.join(libraryPath, "d_FRM_SHEET.xml"), 'utf8')
                }
                //go into VertexDatabase>Table>Records and loop through each record.
                //inside each record find a Cell with the name "CODE" and get the value of it.
                const parser = new DOMParser();
                const xmlDoc = parser.parseFromString(xmlContent, 'text/xml');
                const records = xmlDoc.getElementsByTagName('Record');
                const codes = [];
                for (let i = 0; i < records.length; i++) {
                    const record = records[i];
                    const cells = record.getElementsByTagName('Cell');
                    for (let j = 0; j < cells.length; j++) {
                        const cell = cells[j];
                        const cellName = cell.getAttribute('Name');
                        if (cellName === 'CODE' || cellName === 'SHTCODE') {
                            const cellValue = cell.textContent;
                            //check if cellValue is not already in the codes array.
                            if (!codes.includes(cellValue)) {
                                codes.push(cellValue);
                            }
                            break; // No need to check other cells in this record
                        }
                    }
                }
                // Found the folder and processed it, no need to check other workspaces
                return codes;;
            }} 
            catch (error) {
                console.error(`Error scanning for macro codes: ${error}`);
                return [];
            }}
    return [];
});

