//used for autofill field options of get_macro_param, get_obj_param etc.
connection.onRequest('custom/getObjectParameters', async (params) => {
    const { command, objectType, uri, variableName, line } = params;
    // Dynamic macro fields

    const excludeList = new Set(['BROWSER_PATH', 'CATEGORY','NAME_2D','NAME_3DACC','NAME_3DCRS','THUMBNAIL_ID','FORM_FILE','HNDPROG','INPUT_STYLE','NAME_INI','PREPROG'])

    if ((command === 'get_obj_param' || command === 'set_obj_param') && objectType === 'macro' && uri && variableName != null) {
        const document = documents.get(uri);
        if (document) {
            const macroInfo = resolveMacroIdentity(document, variableName, line);
            if (macroInfo) {
                const records = getMacroRecordFields(macroInfo.library, macroInfo.code);
                //look through records for any called "parameters" and split those into own sections on |
                const outRecords = []
                for (const record in records) {
                    if (records[record].label === 'PARAMETERS') {
                        const paramRecords = records[record].documentation.split('Value in database: ')[1].split('|')
                        for (const paramRecord in paramRecords) {
                            const key = paramRecords[paramRecord].split("=")[0]
                            const value = paramRecords[paramRecord].split("=")[1]
                            outRecords.push({ label: key, documentation: 'PARAMETER RECORD, standard value: ' + value})
                        }
                    } else {
                        if (excludeList.has(records[record].label)) {
                            continue
                        } else {
                            outRecords.push(records[record])
                        }
                    }
                }
                return outRecords
            }
        }
    }

    //same handling for joint objects:
    if ((command === 'get_obj_param' || command === 'get_joint_param' 
        || command === 'set_joint_param' || command === 'set_djparam' 
        || command === 'set_obj_param') && objectType === 'joint') {
        const document = documents.get(uri);
        if (document) {
            const jointInfo = resolveJointIdentity(document, variableName, line);
            if (jointInfo) {
                const records = getJointRecordFields(jointInfo.library, jointInfo.code);
                //look through records for any called "parameters" and split those into own sections on |
                const outRecords = []
                for (const record in records) {
                    if (records[record].label === 'PARAMETERS') {
                        const paramRecords = records[record].documentation.split('Value in database: ')[1].split('|')
                        for (const paramRecord in paramRecords) {
                            const key = paramRecords[paramRecord].split("=")[0]
                            const value = paramRecords[paramRecord].split("=")[1]
                            outRecords.push({ label: key, documentation: 'PARAMETER RECORD, standard value: ' + value})
                        }
                    } else {
                        if (excludeList.has(records[record].label)) {
                            continue
                        } else {
                            outRecords.push(records[record])
                        }
                    }
                }
                return outRecords
            }
        }
    }

    // Return parameters based on command and object type
    if (parameterConfigurations[command]) {
        if (parameterConfigurations[command][objectType]) {
            return parameterConfigurations[command][objectType];
        } else if (parameterConfigurations[command]['any']) {
            return parameterConfigurations[command]['any'];
        } else if (parameterConfigurations[command]['generic']) {
            return parameterConfigurations[command]['generic'];
        }
    }

    return [];
});

