//---------------------------------------------------------------------------------
//semantic tokens provider (handling semantic highlighting)------------------------
//---------------------------------------------------------------------------------

connection.languages.semanticTokens.on(async (params) => {

    
    console.time('Semantic Tokens Processing Time');
    console.time(`Semantic Tokens Setup for ${params.textDocument.uri}`);
    //check if globalSettings exists and if not, call it
    if (!globalSettings) {
        globalSettings = await connection.workspace.getConfiguration('languageServerExample');
    }


    if (!globalSettings.semanticHighlighting) {
        console.timeEnd(`Semantic Tokens Setup for ${params.textDocument.uri}`);
        console.timeEnd('Semantic Tokens Processing Time');
        return { data: [] };
    }

    const document = documents.get(params.textDocument.uri);
    if (document === undefined) {
        console.timeEnd(`Semantic Tokens Setup for ${params.textDocument.uri}`);
        console.timeEnd('Semantic Tokens Processing Time');
        return { data: [] };
    }

    console.timeEnd(`Validation To Semantic Tokens Request for ${document.uri}::${document.version}`);

    const semanticExtractionKey = `${document.uri}::${document.version}`;
    console.timeEnd(`Semantic Tokens Setup for ${params.textDocument.uri}`);
    console.time(`Semantic Tokens Extraction Refresh for ${document.uri}`);
    if (lastSemanticExtractionKey !== semanticExtractionKey) {
        await extractVariables(document.getText(), true, true);
        //await validateTextDocument(document);
        lastSemanticExtractionKey = semanticExtractionKey;
    }
    console.timeEnd(`Semantic Tokens Extraction Refresh for ${document.uri}`);

    const lines = document.getText().split(/\r?\n/);
    variableTypes.length = 0;
    variableTypeCollection(lines);
    const fileSections = parseFileSections(lines);

    //const constVariables = documentConstVariables.get(document.uri) || new Set();
    const builder = new node_1.SemanticTokensBuilder();

    if (variableTypes.length === 0) {
        console.timeEnd(`Semantic Tokens Scan for ${document.uri}`);
        console.timeEnd('Semantic Tokens Processing Time');
        console.timeEnd('complete run time');
        return builder.build();
    }
    
    let match;
    // Apply semantic highlighting based on variable types
    console.time(`Semantic Tokens Scan for ${document.uri}`);
    for (let i = 0; i < lines.length; i++) {
        let line = lines[i];
        
        const trimmedLine = line.trim();

        //stop if line includes START OF DEBUG in FILE or START OF DEBUG in SECTION
        if (isDebugDocumentText(line)) {
            break;
        }

        if (trimmedLine.startsWith('!')) {
            continue;
        }

        //ignore empty lines
        if (trimmedLine === '') {
            continue;
        }

        //ignore line if it starts with # include
        if (trimmedLine.startsWith('#include')) {
            continue;
        }
        //ignore line if it starts with ##included_from
        if (trimmedLine.startsWith('##included_from')) {
            continue;
        }
        //ignore line if it starts with #
        if (trimmedLine.startsWith('#')) {
            continue;
        }
        //ignore line if it starts with call
        if (trimmedLine.startsWith('call ')) {
            continue;
        }
        //ignore line if it starts with debug
        if (trimmedLine.startsWith('debug ')) {
            continue;
        }

        // Skip comments
        line = stripValidationComment(line);

        //ignore line if it ends with ##
        if (line.trim().endsWith('##')) {
            continue;
        }

        while ((match = variableRegex.exec(line)) !== null) {
            const varName = match[1];
            const startChar = match.index;
            const length = match[0].length;

            if (globalSettings.debugValidationCommands) {
                // Skip if inside quotes, keywords, or vector patterns (existing logic)
                if (//keywordLabelsSet.has(varName) ||
                    isInsideQuotes(line, startChar) ||
                    //skip this if strict mode is enabled.
                    (!globalSettings.strictMode && /[PXYZN](\d+)?$/.test(varName))) {
                    continue;
                }
            } else {
                if (keywordLabelsSet.has(varName) ||
                    isInsideQuotes(line, startChar) ||
                    //skip this if strict mode is enabled.
                    (!globalSettings.strictMode && /[PXYZN](\d+)?$/.test(varName))) {
                    continue;
                }
            }


            //if no exclusion rule is hit, proceed------------------------------------------------------

            if (globalSettings.debugValidationCommands) {
                // Determine token type based on variable state at this line
                //check first if varName is in commandNames set and if so, set object type to 'validatedCommand'
                if (commandNamesSet.has(varName)) {
                    let tokenType = getTokenTypeForObjectType('validatedCommand');
                    let tokenModifier = 0;
                    builder.push(i, startChar, length, tokenType, tokenModifier);
                    continue;
                }
            }

            const currentType = getCurrentVariableType(varName, i, fileSections);
            if (currentType === null) {
                continue; // No type information available
            }
            let tokenType = getTokenTypeForObjectType(currentType);
            //let tokenModifier = constVariables.has(varName) ? 1 : 0;
            let tokenModifier = 0;

            if (tokenType !== 0 || tokenModifier !== 0) {
                builder.push(i, startChar, length, tokenType, tokenModifier);
            }
        }
    }
    console.timeEnd(`Semantic Tokens Scan for ${document.uri}`);
    console.timeEnd('Semantic Tokens Processing Time');
    console.timeEnd('complete run time');

    return builder.build();
});

