// This handler provides the initial list of the completion items (all keywords, variables handled in extension.js).
connection.onCompletion((_textDocumentPosition) => {
    let completionItems = [];
    
    keywords.forEach((keyword, index) => {
        const hasMultilineInsertText = typeof keyword.insertText === 'string' && keyword.insertText.includes('\n');

        // Add the standard keyword version
        const standardItem = {
            label: keyword.label,
            kind: node_1.CompletionItemKind.Keyword,
            data: index + 1,
            //detail: keyword.detail,
            documentation: keyword.documentation,
            // Always apply multiline block templates when user picks the normal completion item.
            insertText: hasMultilineInsertText ? keyword.insertText : undefined,
            insertTextFormat: hasMultilineInsertText ? node_1.InsertTextFormat.PlainText : undefined
        };
        
        completionItems.push(standardItem);
        
        // Add snippet version if the setting is enabled and the keyword has an insertText
        if (globalSettings.useExpandedSyntax && keyword.insertText) {
            const snippetItem = {
                label: `${keyword.label} (snippet)`,
                kind: node_1.CompletionItemKind.Snippet,
                data: (index + 1), // Use a different data ID
                //detail: keyword.detail,
                documentation: keyword.documentation,
                insertText: keyword.insertText,
                insertTextFormat: node_1.InsertTextFormat.Snippet
            };
            
            completionItems.push(snippetItem);
        }
    });
    
    return completionItems;
});

connection.onCompletionResolve((item) => {
    if (item.data <= keywords.length) {
        const keyword = keywords[item.data - 1];
        if (keyword) {
            const resolveitem = `${(keyword.documentation ? keyword.documentation.replace(/\n/g, '\n') : '')}\n\n---\n${(keyword.detail ? keyword.detail.replace(/\n/g, '\n') : '')}`;
            item.documentation = {
                kind: 'markdown',
                value: resolveitem
            };
        }
    }
    return item;
});

connection.onSignatureHelp((params) => {
    const document = documents.get(params.textDocument.uri);
    if (!document) {
        return null;
    }

    const text = document.getText();
    const offset = document.offsetAt(params.position);
    const context = getCommandContext(text, offset);
    if (!context) {
        return null;
    }

    const { insideParams, afterParams } = buildParamLabels(context.name);
    if (!insideParams.length && !afterParams.length) {
        return null;
    }

    if (!context.inParens && context.hadParens && afterParams.length === 0) {
        // Command parameters are inside parentheses only and they are already closed.
        return null;
    }

    const effectiveAfterParams = context.inParens
        ? afterParams
        : (afterParams.length ? afterParams : insideParams);

    const allParams = context.inParens
        ? [...insideParams, ...afterParams]
        : [...effectiveAfterParams];

    if (!allParams.length) {
        return null;
    }

    let active;
    if (context.inParens) {
        if (context.insideCommas >= insideParams.length) {
            return null;
        }
        active = context.insideCommas;
    }
    else {
        if (context.afterCommas >= effectiveAfterParams.length) {
            return null;
        }
        active = context.afterCommas;
    }

    const signatureLabel = context.inParens
        ? `${context.name}(${insideParams.join(', ')})${afterParams.length ? ' ' + afterParams.join(', ') : ''}`
        : `${context.name} ${effectiveAfterParams.join(', ')}`;

    return {
        signatures: [
            {
                label: signatureLabel,
                parameters: allParams.map(label => ({ label }))
            }
        ],
        activeSignature: 0,
        activeParameter: active
    };
});

