//event that is fired on opening a document.
documents.onDidOpen(async e => {
    console.time(`Document Open Processing for ${e.document.uri}::${e.document.version}`);
    // Prime semantic type state when opening so tab switches colorize immediately.
    const currentText = e.document.getText();
    previousDocumentVersions.set(e.document.uri, currentText);
    updateIndexForFile(uriToFsPath(e.document.uri), currentText, false);
    await validateTextDocumentExclusive(e.document);
    lastSemanticExtractionKey = `${e.document.uri}::${e.document.version}`;
    console.timeEnd(`Document Open Processing for ${e.document.uri}::${e.document.version}`);
});

// The content of a text document has changed. This event is emitted
// when the text document first opened or when its content has changed.
//      every time the document changes, we validate for errors again
documents.onDidChangeContent(change => {
    //takes 6milliseconds on walldetailing 2025-11-02
    console.time(`Content Change Processing for ${change.document.uri}::${change.document.version}`);
    
    const currentText = change.document.getText();
    
    const previousText = previousDocumentVersions.get(change.document.uri) || "";
    let runflag = false;

    if (isDebugDocumentText(currentText)) {
        runflag = true;
    }

    //check differences between current version (user did something) and previous version
    console.time(`Content Change Diff Detection for ${change.document.uri}::${change.document.version}`);
    let result = findTextDifference(previousText, currentText);
    console.timeEnd(`Content Change Diff Detection for ${change.document.uri}::${change.document.version}`);
    if (result !== null) {
        //if doing certain additions to file, extract variables again.
        if (result.added.trim() === '=' || result.removed.trim() === '=' || result.added.trim().length > 3 && !(result.newLine.trim().startsWith('##included_from'))){
            extractVariables(currentText, true, true);
            runflag = true;
        }
        //reload variables as long as line being modified contains =
        if (result.newLine.trim().includes('=')){
            extractVariables(currentText, true, true);
            runflag = true;
        }
        //if this is open document "change", then extract variables and hovers. (first time doc is opened)
        if (previousText.length === 0 && !runflag) {
            extractVariables(currentText, true, true);
            runflag = true;
        }
        if (result.newLine.trim().endsWith('"') && !runflag){
            extractVariables(currentText, true, true);
            runflag = true;
        } 
        if (result.newLine.trim().startsWith('##included_from') && result.newLine.endsWith('\r') && !runflag &&result.removed.length < 1) {
            extractVariables(currentText, true, true);
            runflag = true;
        }
        if (prevnewline.trim().startsWith('##included_from') && (result.newLine === '\r' || result.newLine === '\r\n') && !runflag) {
            extractVariables(currentText, true, true);
            runflag = true;
        }
        //check if current document's uri is different from the previous document's uri, if so get new variables.
        if (change.document.uri !== prevdocuri && prevdocuri !== "" && !runflag) {
            extractVariables(currentText, true, true);
            runflag = true;
        }
        //set this document uri to prevdocuri
        prevdocuri = change.document.uri;

        //prev newline
        prevnewline = result.newLine;
    }

    scheduleDeferredWorkspaceSync(change.document.uri, currentText, {
        uri: change.document.uri,
        crossFileRelevant: result !== null && editMayAffectCrossFileDiagnostics(result),
        localSlotRelevant: result !== null && editMayAffectLocalSlotDiagnostics(result),
    });

    console.timeEnd(`Content Change Processing for ${change.document.uri}::${change.document.version}`);
});

//---------------------------------------------------------------------------------
//document close handling---------------------------------------------------------
//---------------------------------------------------------------------------------

documents.onDidClose(e => {
    //does run when closing a document, not when swapping document, only when closing a editor "document"
    documentSettings.delete(e.document.uri);
    docCache.delete(e.document.uri);
    updateIndexForFile(uriToFsPath(e.document.uri), undefined, true);
    recentDiagnosticsCache.delete(e.document.uri);
    scheduleConnectedDiagnosticsRefresh(e.document.uri, { force: true });
});

//---------------------------------------------------------------------------------
//end of document event handlers---------------------------------------------------
//---------------------------------------------------------------------------------

//@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@

//---------------------------------------------------------------------------------
//functions------------------------------------------------------------------------
//---------------------------------------------------------------------------------

function extractFunctionParameters(fileContent, targetSection) {
    const extracted = targetSectionSupport.extractCallParametersFromText(fileContent, targetSection);
    const lines = String(fileContent || '').split('\n');
    const parameters = [];
    for (let i = 0; i < extracted.length; i++) {
        const item = extracted[i];
        const line = lines[item.lineIndex] || '';
        const parameter = {
            variableName: item.variableName,
            parameterName: item.parameterName
        };
        const commentIndex = findValidationCommentIndex(line);
        if (commentIndex !== -1) {
            let comment = line.substring(commentIndex + 2);
            comment = comment.split('"')[1];
            if (comment) {
                parameter.comment = comment;
            }
        }
        parameters.push(parameter);
    }
    return parameters;
}

function getExpectedCallParamCount(fileContent, targetSection) {
    return targetSectionSupport.getExpectedCallParamCountFromText(fileContent, targetSection);
}

function isCallParamValidationEnabled() {
    return globalSettings?.calls?.validateParameterCount !== false;
}

function isUnclosedResourceCheckEnabled() {
    return globalSettings?.diagnostics?.warnUnclosedResources !== false;
}

function getAdtFileLinesForResourceCheck(normalizedPath) {
    if (!normalizedPath) {
        return null;
    }
    for (const document of documents.all()) {
        const docPath = normalizeFsPath(uriToFsPath(document.uri));
        if (docPath === normalizedPath) {
            return document.getText().split(/\r?\n/);
        }
    }
    const entry = workspaceDeclarationIndex.get(normalizedPath);
    const diskPath = entry?.uri ? uriToFsPath(entry.uri) : normalizedPath;
    try {
        if (diskPath && fs.existsSync(diskPath)) {
            return fs.readFileSync(diskPath, 'utf8').split(/\r?\n/);
        }
        if (fs.existsSync(normalizedPath)) {
            return fs.readFileSync(normalizedPath, 'utf8').split(/\r?\n/);
        }
    } catch (_error) {
        return null;
    }
    return null;
}

function resolvePathForResourceCheck(rawPath) {
    const resolved = resolveVertexFilePath(rawPath);
    if (!resolved) {
        return null;
    }
    return normalizeFsPath(resolved);
}

function getDirectIncludeParentsForResourceCheck(targetNormalized) {
    const parents = [];
    const normalizedTarget = normalizeFsPath(targetNormalized);
    workspaceDeclarationIndex.forEach((entry, otherPath) => {
        for (let i = 0; i < (entry.includeLinks || []).length; i++) {
            const link = entry.includeLinks[i];
            if (link.targetPath === normalizedTarget) {
                parents.push({
                    fromPath: otherPath,
                    line: link.line,
                    lineText: link.lineText || '',
                    targetSection: link.targetSection || '',
                    targetPath: link.targetPath
                });
            }
        }
    });
    return parents;
}

function getOutgoingIncludeLinksForResourceCheck(fromNormalized) {
    const entry = workspaceDeclarationIndex.get(normalizeFsPath(fromNormalized));
    if (!entry) {
        return [];
    }
    return (entry.includeLinks || []).map((link) => ({
        targetPath: link.targetPath,
        line: link.line,
        lineText: link.lineText || '',
        targetSection: link.targetSection || ''
    }));
}

function collectUnclosedResourceDiagnostics(lines, textDocument, lineOffsets) {
    const diagnosticsForFile = [];
    if (!isUnclosedResourceCheckEnabled()) {
        return diagnosticsForFile;
    }
    const currentFilePath = normalizeFsPath(uriToFsPath(textDocument.uri));
    if (!currentFilePath) {
        return diagnosticsForFile;
    }
    const currentLines = lines;
    const issues = unclosedResources.collectUnclosedResourceIssues({
        currentFilePath,
        getFileLines: (normalizedPath) => {
            if (normalizeFsPath(normalizedPath) === currentFilePath) {
                return currentLines;
            }
            return getAdtFileLinesForResourceCheck(normalizedPath);
        },
        resolvePath: resolvePathForResourceCheck,
        normalizePath: normalizeFsPath,
        getDirectIncludeParents: getDirectIncludeParentsForResourceCheck,
        getOutgoingIncludeLinks: getOutgoingIncludeLinksForResourceCheck,
        filePathToUri: (filePath) => {
            const entry = workspaceDeclarationIndex.get(normalizeFsPath(filePath));
            if (entry?.uri) {
                return entry.uri;
            }
            try {
                const diskPath = uriToFsPath(fsPathToUri(filePath)) || filePath;
                return fsPathToUri(diskPath);
            } catch (_error) {
                return fsPathToUri(filePath);
            }
        }
    });

    for (let i = 0; i < issues.length; i++) {
        const issue = issues[i];
        const lineText = lines[issue.line] || '';
        const lineStartOffset = typeof lineOffsets?.[issue.line] === 'number'
            ? lineOffsets[issue.line]
            : lines.slice(0, issue.line).join('\n').length + (issue.line > 0 ? 1 : 0);
        const startChar = Math.max(0, issue.startChar || 0);
        const endChar = Math.max(startChar + 1, issue.endChar || lineText.length);
        const diagnostic = {
            severity: issue.severity === 'information'
                ? node_1.DiagnosticSeverity.Information
                : node_1.DiagnosticSeverity.Warning,
            range: {
                start: textDocument.positionAt(lineStartOffset + startChar),
                end: textDocument.positionAt(lineStartOffset + endChar),
            },
            message: issue.message,
            source: 'ADT-Syntax',
            code: issue.code,
            data: {
                line: issue.line
            }
        };
        if (hasDiagnosticRelatedInformationCapability && issue.related && issue.related.length > 0) {
            diagnostic.relatedInformation = issue.related.map((related) => ({
                location: {
                    uri: related.uri,
                    range: {
                        start: { line: related.line, character: related.startChar || 0 },
                        end: { line: related.line, character: Math.max(related.endChar || 1, 1) }
                    }
                },
                message: related.message
            }));
        }
        diagnosticsForFile.push(diagnostic);
    }
    return diagnosticsForFile;
}

function getExpectedCallParamCountForResolvedPath(resolvedPath, targetSection) {
    const normalized = normalizeFsPath(resolvedPath);
    if (!normalized) {
        return 0;
    }
    const fileContent = loadLinkedFileText(resolvedPath);
    if (fileContent) {
        return getExpectedCallParamCount(fileContent, targetSection || null);
    }
    if (!targetSection) {
        const entry = workspaceDeclarationIndex.get(normalized);
        if (entry && typeof entry.expectedCallParamCount === 'number') {
            return entry.expectedCallParamCount;
        }
    }
    return 0;
}

function buildMissingCallParamInsertText(missingCount) {
    if (!missingCount || missingCount <= 0) {
        return '';
    }
    return ',""'.repeat(missingCount);
}

function analyzeCallParamSitesOnLine(line, lineIndex) {
    const sites = [];
    if (!line || !/\bcall\b/i.test(line)) {
        return sites;
    }

    const commandRegex = /\bcall\s*\(/ig;
    let match;
    while ((match = commandRegex.exec(line)) !== null) {
        if (isInsideQuotes(line, match.index)) {
            continue;
        }

        const openParenIndex = match.index + match[0].length - 1;
        const closeParenIndex = findMatchingParenIndex(line, openParenIndex);
        if (closeParenIndex === -1) {
            continue;
        }

        let startIndex = match.index;
        const prefix = line.substring(0, match.index);
        const assignmentMatch = prefix.match(/([A-Za-z][A-Za-z0-9_]*\$?)\s*=\s*$/);
        if (assignmentMatch) {
            startIndex = prefix.length - assignmentMatch[0].length;
        }

        const segment = line.substring(startIndex, closeParenIndex + 1).trim();
        const parsed = parseCommand(segment, segment, false);
        if (!parsed ||
            parsed.functionName.toLowerCase() !== 'call' ||
            parsed.insideParams.length < 1 ||
            !isValidCallPathParameter(parsed.insideParams[0])) {
            continue;
        }

        const targets = [];
        appendResolvedCallTarget(targets, parsed.insideParams[0], '');
        if (targets.length === 0) {
            continue;
        }

        const argCount = parsed.insideParams.length - 1;
        const expected = getExpectedCallParamCountForResolvedPath(
            targets[0].resolvedPath,
            targets[0].targetSection
        );
        if (expected <= 0) {
            continue;
        }

        sites.push({
            lineIndex,
            argCount,
            expected,
            missingCount: Math.max(0, expected - argCount),
            extraCount: Math.max(0, argCount - expected),
            openParenIndex,
            closeParenIndex,
            insideParams: parsed.insideParams,
            resolvedPath: targets[0].resolvedPath,
            calleeDisplayPath: targets[0].rawPath,
        });
    }

    return sites;
}

function findCallParamRangesInParen(line, openParenIndex, closeParenIndex) {
    const content = line.substring(openParenIndex + 1, closeParenIndex);
    const ranges = [];
    let i = 0;

    while (i < content.length) {
        while (i < content.length && (content[i] === ' ' || content[i] === ',')) {
            i++;
        }
        if (i >= content.length) {
            break;
        }

        const paramStart = openParenIndex + 1 + i;
        let inQuotes = false;
        let parenDepth = 0;
        while (i < content.length) {
            const ch = content[i];
            if (ch === '"' && parenDepth === 0) {
                inQuotes = !inQuotes;
            } else if (!inQuotes) {
                if (ch === '(') {
                    parenDepth++;
                } else if (ch === ')') {
                    if (parenDepth > 0) {
                        parenDepth--;
                    }
                } else if (ch === ',' && parenDepth === 0) {
                    break;
                }
            }
            i++;
        }

        ranges.push({
            start: paramStart,
            end: openParenIndex + 1 + i,
        });
    }

    return ranges;
}

function buildExtraCallParamRemovalRange(line, openParenIndex, closeParenIndex, expected, paramRanges) {
    const firstExtraIndex = expected + 1;
    if (!paramRanges || paramRanges.length <= firstExtraIndex) {
        return null;
    }

    let deleteStart = paramRanges[firstExtraIndex].start;
    while (deleteStart > openParenIndex + 1 && /\s/.test(line[deleteStart - 1])) {
        deleteStart--;
    }
    if (deleteStart > openParenIndex + 1 && line[deleteStart - 1] === ',') {
        deleteStart--;
    }
    while (deleteStart > openParenIndex + 1 && /\s/.test(line[deleteStart - 1])) {
        deleteStart--;
    }

    return {
        start: deleteStart,
        end: closeParenIndex,
    };
}

function collectCallParamCountDiagnostics(lines, textDocument, lineOffsets) {
    const diagnostics = [];
    if (!isCallParamValidationEnabled()) {
        return diagnostics;
    }

    const fileSections = parseFileSections(lines);

    for (let i = 0; i < lines.length; i++) {
        let line = lines[i];
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith('!')) {
            continue;
        }
        if (fileSections && isLineInVerificationIgnoredSection(i, fileSections)) {
            continue;
        }
        line = stripValidationComment(line);
        const bangCommentIndex = findInlineBangCommentIndex(line);
        const codeLine = bangCommentIndex === -1 ? line : line.slice(0, bangCommentIndex);

        const sites = analyzeCallParamSitesOnLine(codeLine, i);
        for (let s = 0; s < sites.length; s++) {
            const site = sites[s];
            const lineStartOffset = typeof lineOffsets?.[i] === 'number'
                ? lineOffsets[i]
                : lines.slice(0, i).join('\n').length + (i > 0 ? 1 : 0);
            const range = {
                start: textDocument.positionAt(lineStartOffset + site.openParenIndex),
                end: textDocument.positionAt(lineStartOffset + site.closeParenIndex + 1),
            };

            if (site.missingCount > 0) {
                diagnostics.push({
                    severity: node_1.DiagnosticSeverity.Error,
                    range,
                    message: `call expects ${site.expected} parameters but ${site.argCount} were provided`,
                    source: 'ADT-Syntax',
                    code: 'vertexadt/missing-call-params',
                    data: {
                        line: i,
                        insertOffset: site.closeParenIndex,
                        missingCount: site.missingCount,
                        expected: site.expected,
                        actual: site.argCount,
                        calleeDisplayPath: site.calleeDisplayPath,
                    },
                });
            } else if (site.extraCount > 0) {
                const paramRanges = findCallParamRangesInParen(codeLine, site.openParenIndex, site.closeParenIndex);
                const removalRange = buildExtraCallParamRemovalRange(
                    codeLine,
                    site.openParenIndex,
                    site.closeParenIndex,
                    site.expected,
                    paramRanges
                );
                diagnostics.push({
                    severity: node_1.DiagnosticSeverity.Warning,
                    range,
                    message: `call expects ${site.expected} parameters but ${site.argCount} were provided`,
                    source: 'ADT-Syntax',
                    code: 'vertexadt/extra-call-params',
                    data: {
                        line: i,
                        extraCount: site.extraCount,
                        expected: site.expected,
                        actual: site.argCount,
                        calleeDisplayPath: site.calleeDisplayPath,
                        removeStart: removalRange?.start,
                        removeEnd: removalRange?.end,
                    },
                });
            }
        }
    }

    return diagnostics;
}

function collectUnknownSectionDiagnostics(lines, textDocument, lineOffsets) {
    const diagnostics = [];
    const fileSections = parseFileSections(lines);

    for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith('!')) {
            continue;
        }
        if (fileSections && isLineInVerificationIgnoredSection(i, fileSections)) {
            continue;
        }

        const sites = targetSectionSupport.collectNamedSectionSuffixes(line);
        for (let s = 0; s < sites.length; s++) {
            const site = sites[s];
            if (!site.targetSection) {
                continue;
            }
            const resolved = resolveVertexFilePath(site.filePath);
            if (!resolved) {
                continue;
            }
            const targetText = loadLinkedFileText(resolved);
            if (targetText === null || targetText === undefined) {
                continue;
            }
            const sectionNames = targetSectionSupport.listUniqueTargetSectionNames(targetText);
            if (!targetSectionSupport.isUnknownTargetSectionName(site.targetSection, sectionNames)) {
                continue;
            }

            const lineStartOffset = typeof lineOffsets?.[i] === 'number'
                ? lineOffsets[i]
                : lines.slice(0, i).join('\n').length + (i > 0 ? 1 : 0);

            diagnostics.push({
                severity: node_1.DiagnosticSeverity.Warning,
                range: {
                    start: textDocument.positionAt(lineStartOffset + site.sectionStart),
                    end: textDocument.positionAt(lineStartOffset + site.sectionEnd)
                },
                message: `Unknown section '${site.targetSection}' in ${path.basename(resolved)}`,
                source: 'ADT-Syntax',
                code: 'vertexadt/unknown-section'
            });
        }
    }

    return diagnostics;
}

function buildCallParamWorkspaceEditsForContent(uri, content) {
    const edits = [];
    if (!content) {
        return edits;
    }

    const lines = content.split('\n');
    for (let i = 0; i < lines.length; i++) {
        let line = lines[i];
        line = stripValidationComment(line);
        const bangCommentIndex = findInlineBangCommentIndex(line);
        const codeLine = bangCommentIndex === -1 ? line : line.slice(0, bangCommentIndex);
        const sites = analyzeCallParamSitesOnLine(codeLine, i);
        for (let s = 0; s < sites.length; s++) {
            const site = sites[s];
            if (site.missingCount > 0) {
                edits.push({
                    uri,
                    line: i,
                    startCharacter: site.closeParenIndex,
                    endCharacter: site.closeParenIndex,
                    newText: buildMissingCallParamInsertText(site.missingCount),
                });
                continue;
            }
            if (site.extraCount > 0) {
                const paramRanges = findCallParamRangesInParen(codeLine, site.openParenIndex, site.closeParenIndex);
                const removalRange = buildExtraCallParamRemovalRange(
                    codeLine,
                    site.openParenIndex,
                    site.closeParenIndex,
                    site.expected,
                    paramRanges
                );
                if (removalRange) {
                    edits.push({
                        uri,
                        line: i,
                        startCharacter: removalRange.start,
                        endCharacter: removalRange.end,
                        newText: '',
                    });
                }
            }
        }
    }

    edits.sort((a, b) => {
        if (a.line !== b.line) {
            return b.line - a.line;
        }
        return b.startCharacter - a.startCharacter;
    });
    return edits;
}

function buildWorkspaceEditFromCallParamEdits(editEntries) {
    const changes = {};
    for (let i = 0; i < editEntries.length; i++) {
        const entry = editEntries[i];
        if (!changes[entry.uri]) {
            changes[entry.uri] = [];
        }
        changes[entry.uri].push({
            range: {
                start: { line: entry.line, character: entry.startCharacter },
                end: { line: entry.line, character: entry.endCharacter },
            },
            newText: entry.newText,
        });
    }
    return { changes };
}

function buildMissingCallParamWorkspaceEditsForContent(uri, content) {
    return buildCallParamWorkspaceEditsForContent(uri, content);
}

function buildWorkspaceEditFromMissingCallParamEdits(editEntries) {
    return buildWorkspaceEditFromCallParamEdits(editEntries);
}

function extractReturnValues(fileContent) {
    const returnValues = [];
    const lines = fileContent.split('\n');
    
    // Look for any line setting a return string before a return statement
    let returnVar = '';
    let returnFormat = '';

    //first loop through text document looking for exit command to get return variable name.
    //exampple: exit Ret$
    for (let i = 0; i < lines.length; i++) {
        const line = lines[i].trim();
        // Look for the exit command
        if (line.trim().startsWith('exit')) {
            const exitMatch = line.match(/exit\s+(\w+\$)/);
            if (exitMatch) {
                returnVar = exitMatch[1];
            }
        }
    }
    
    for (let i = 0; i < lines.length; i++) {
        const line = lines[i].trim();
        
        // Look for the return variable assignment
        
        // Look for string assignments that include field markers like "KEY=..."
        if (line.includes('=') && line.includes('"') && line.includes('&') && line.includes(returnVar)) {
            const varMatch = line.match(/^\s*([a-zA-Z][a-zA-Z0-9_]*\$)\s*=/);
            if (varMatch) {
                returnVar = varMatch[1];
                
                // Extract the format by looking at the literals in quotes
                const formatParts = line.match(/"([^"]*?)"/g) || [];
                const fields = [];
                
                for (const part of formatParts) {
                    // Look for field names in the format KEY=
                    const fieldMatch = part.match(/"([A-Z0-9_]+)=|"\|([A-Z0-9_]+)=/);
                    if (fieldMatch) {
                        // Use the first captured group that isn't undefined
                        fields.push(fieldMatch[1] || fieldMatch[2]);
                    }
                }
                
                if (fields.length > 0) {
                    returnFormat = fields;

                    //search for variable hovers for each field.
                    extractVariables(fileContent,true,false)

                    
                    // For each field, create two completion items:
                    // 1. The strfield extraction
                    // 2. The variable declaration
                    fields.forEach(field => {
                        //check if field has a hover text in hovervariables or hoverstringvariables arrays
                        let hovertext = "";
                        let hovervariable = "";
                        for (let i = 0; i < hovervariables.length; i++) {
                            if (hovervariables[i][0] === field) {
                                try {
                                    hovervariable = hovervariables[i][1]
                                    if (hovervariable.length > 0) {
                                        hovertext = hovervariables[i][1];
                                        break;
                                    }
                                } catch {}
                            }
                        }
                        let extrainfo = "";
                        if ((hovertext.length) > 0) {
                            //extrainfo = `;!"${hovertext}"`
                            hovertext = `\`\`\`vertexadt
"Extract" ${field} "from return string"
!Variableinfo: ${hovertext}
\`\`\``;
                            
                        } else {
                            //extrainfo = ``
                            hovertext = `\`\`\`vertexadt
"Extract" ${field} "from return string"
\`\`\``;
                            
                        }
                        const lowerField = field.toLowerCase();
                        returnValues.push({
                            label: `ret${lowerField}$ = strfield(Ret$,"${field}") ${extrainfo}\nret${lowerField} = ret${lowerField}$ ${extrainfo}`,
                            kind: "Snippet",
                            detail: hovertext
                        });
                    });
                }
            }
        }
    }
    
    return returnValues;
}

function getDirectoryContents(dirPath) {
    try {
        const results = [];

        if (!fs.existsSync(dirPath) || !fs.lstatSync(dirPath).isDirectory()) {
            return results;
        }

        const entries = fs.readdirSync(dirPath);

        for (const entry of entries) {
            const fullPath = path.join(dirPath, entry);
            const isDirectory = fs.lstatSync(fullPath).isDirectory()
            
            if (isDirectory) {
                results.push(`${entry}/`);
            } else {
                // check if entry have certain file extensions and ignore them if so.
                if (!(entry.endsWith('.vxm') || entry.endsWith('.ico') || entry.endsWith('.bmp') || entry.endsWith('.jpg') || entry.endsWith('.vxp') || entry.endsWith('.png') || entry.endsWith('.dwg') || entry.endsWith('.dxf') || entry.startsWith('D_'))) {
                    // ignore this file
                    results.push(entry);
                }
            }
        }

        // Sort with directories first, then files
        results.sort((a, b) => {
            const aIsDir = a.endsWith('/');
            const bIsDir = b.endsWith('/');
            
            if (aIsDir && !bIsDir) return -1;
            if (!aIsDir && bIsDir) return 1;
            return a.localeCompare(b);
        });

        return results;
    } catch (error) {
        console.error("Error reading directory:", error);
        return [];
    }
}

function searchInCustomAndSystem(workspaceRoot, relativePath) {
    const results = [];
    

    let customname = "custom";
    if (workspaceFolders) {
        //loop through each workspaces folder.
        for (let i = 0; i < workspaceFolders.length; i++) {
            let workspaceFolder = workspaceFolders[i].uri;
            //check if the folder name contains "custom"
            if (workspaceFolder.includes("custom")) {
                //get the full name of that folder.
                customname = workspaceFolder.split('/').pop();
                //replace the %3A with : and replace the / with \
                customname = customname.replace(/\//g, '\\');
                customname = customname.replace('%3A', ':');
    }}}
    
    // Try custom directory first
    const customPath = path.join(workspaceRoot, customname, relativePath);
    if (fs.existsSync(customPath) && fs.lstatSync(customPath).isDirectory()) {
        const customResults = getDirectoryContents(customPath);
        results.push(...customResults);
    }
    
    // Then try system directory
    const systemPath = path.join(workspaceRoot, 'system', relativePath);
    if (fs.existsSync(systemPath) && fs.lstatSync(systemPath).isDirectory()) {
        const systemResults = getDirectoryContents(systemPath);
        // Filter out duplicates that might also exist in custom
        for (const item of systemResults) {
            if (!results.includes(item)) {
                results.push(item);
            }
        }
    }
    
    return results;
}

