function getCodeLine(line) {
    const trimmed = line.trim();
    if (trimmed.startsWith('!')) {
        return '';
    }
    return stripValidationComment(line).trim();
}

function parseFileSections(lines) {
    const sectionMarker = /^#([A-Za-z_][A-Za-z0-9_]*)#$/;
    const open = new Map();
    const sections = [];

    for (let i = 0; i < lines.length; i++) {
        if (!(lines[i].startsWith('#'))) {continue;}
        const m = lines[i].trim().match(sectionMarker);
        if (!m) {
            continue;
        }

        const name = m[1];
        if (!open.has(name)) {
            open.set(name, i);
        } else {
            const start = open.get(name);
            open.delete(name);
            sections.push({
                name,
                markerStart: start,
                markerEnd: i,
                bodyStart: start + 1,
                bodyEnd: i - 1,
            });
        }
    }
    return sections;
}

function getSectionForLine(lineIndex, fileSections) {
    for (let i = 0; i < fileSections.length; i++) {
        const section = fileSections[i];
        if (lineIndex >= section.bodyStart && lineIndex <= section.bodyEnd) {
            return section.name;
        }
    }
    return '';
}

const VERIFICATION_IGNORED_SECTION_NAMES = new Set(['EDIT_FORM']);

function isVerificationIgnoredSectionName(sectionName) {
    return typeof sectionName === 'string' &&
        VERIFICATION_IGNORED_SECTION_NAMES.has(sectionName);
}

function isLineInVerificationIgnoredSection(lineIndex, fileSections) {
    const sectionName = getSectionForLine(lineIndex, fileSections);
    return isVerificationIgnoredSectionName(sectionName);
}

function getVerificationIgnoredRanges(fileSections) {
    const ranges = [];
    for (let i = 0; i < fileSections.length; i++) {
        const section = fileSections[i];
        if (!isVerificationIgnoredSectionName(section.name)) {
            continue;
        }
        if (section.bodyStart <= section.bodyEnd) {
            ranges.push({
                start: section.bodyStart,
                end: section.bodyEnd,
            });
        }
    }
    return ranges;
}

function isLineInIgnoredRanges(lineIndex, ignoredRanges) {
    for (let i = 0; i < ignoredRanges.length; i++) {
        const range = ignoredRanges[i];
        if (lineIndex >= range.start && lineIndex <= range.end) {
            return true;
        }
    }
    return false;
}

function updateValidationControlStacksSilently(lineState) {
    const {
        trimmedLine,
        indentation,
        startsWithIf,
        startsWithEndif,
        startsWithLoop,
        startsWithEndloop,
        startsWithElse,
        beginsWithIfKeyword,
        beginsWithLoopKeyword,
        isInlineIfThen,
        i,
    } = lineState;

    if (startsWithIf && !isInlineIfThen) {
        ifstack.push({ line: i, indentation: indentation });
    } else if (startsWithEndif && ifstack.length > 0) {
        ifstack.pop();
    }

    if (startsWithLoop) {
        loopstack.push({ line: i, indentation: indentation });
    } else if (startsWithEndloop && loopstack.length > 0) {
        loopstack.pop();
    }

    if ((beginsWithIfKeyword || beginsWithLoopKeyword) && !isInlineIfThen) {
        indentstack.push(indentation);
    } else if (startsWithEndif || startsWithEndloop || startsWithElse) {
        if (indentstack.length > 0 && !startsWithElse) {
            indentstack.pop();
        }
    }
}

const INCLUDE_CALL_SECTION_KEYWORDS = new Set(['section', 'sectionoffile']);

function parseIncludeCallPathAndSection(rawPath, lineRemainder) {
    let pathPart = stripPathQuotes(rawPath).replace(/\\/g, '/').trim();
    let targetSection = null;

    const pathSectionMatch = pathPart.match(/^(.+?)\s+([A-Za-z_][A-Za-z0-9_]*)$/);
    if (pathSectionMatch) {
        const token = pathSectionMatch[2];
        if (!INCLUDE_CALL_SECTION_KEYWORDS.has(token.toLowerCase())) {
            targetSection = token;
            pathPart = pathSectionMatch[1].trim();
        } else {
            pathPart = pathPart.replace(/\s+SECTION(?:OFFILE)?$/i, '').trim();
        }
    }

    if (lineRemainder && lineRemainder.trim()) {
        const remMatch = lineRemainder.trim().match(/^([A-Za-z_][A-Za-z0-9_]*)\b/);
        if (remMatch && !INCLUDE_CALL_SECTION_KEYWORDS.has(remMatch[1].toLowerCase())) {
            targetSection = remMatch[1];
        }
    }

    return { filePath: pathPart, targetSection };
}

function lineHasCommand(codeLine, command) {
    return new RegExp(`\\b${command}\\b`, 'i').test(codeLine);
}

function stripQuotedStringsForIfCheck(text) {
    return text
        .replace(/"[^"]*"/g, '""')
        .replace(/'[^']*'/g, "''");
}

function extractIfConditionFromLine(line) {
    const trimmed = stripValidationComment(line).trim();
    if (!/^\bif\b/i.test(trimmed)) {
        return null;
    }

    const thenMatch = trimmed.match(/\bthen\b/i);
    if (!thenMatch || typeof thenMatch.index !== 'number') {
        return null;
    }

    const ifPrefixMatch = trimmed.match(/^\s*if\s+/i);
    if (!ifPrefixMatch) {
        return null;
    }

    return trimmed.slice(ifPrefixMatch[0].length, thenMatch.index).trim();
}

function createIfOperatorScope() {
    return { hasAnd: false, hasOr: false };
}

function recordIfLogicalOperator(scope, kind) {
    if (kind === 'and') {
        scope.hasAnd = true;
    } else {
        scope.hasOr = true;
    }
}

function validateIfOperatorScope(scope) {
    if (scope.hasAnd && scope.hasOr) {
        return 'If condition with both and and or requires parentheses to clarify precedence.';
    }
    return null;
}

function collectIfLogicalOperators(condition) {
    const expr = stripQuotedStringsForIfCheck(condition);
    const operators = [];
    let depth = 0;

    for (let i = 0; i < expr.length; i++) {
        const ch = expr[i];

        if (ch === '(') {
            depth++;
            continue;
        }
        if (ch === ')') {
            depth = Math.max(0, depth - 1);
            continue;
        }

        if (ch === '&' && expr[i + 1] === '&') {
            operators.push({ kind: 'and', style: 'symbol', depth });
            i++;
            continue;
        }
        if (ch === '|' && expr[i + 1] === '|') {
            operators.push({ kind: 'or', style: 'symbol', depth });
            i++;
            continue;
        }

        const remainder = expr.slice(i);
        const andMatch = remainder.match(/^\s+and\b/i);
        if (andMatch) {
            operators.push({ kind: 'and', style: 'word', depth });
            i += andMatch[0].length - 1;
            continue;
        }

        const orMatch = remainder.match(/^\s+or\b/i);
        if (orMatch) {
            operators.push({ kind: 'or', style: 'word', depth });
            i += orMatch[0].length - 1;
        }
    }

    return operators;
}

function getIfConditionOperatorError(condition) {
    if (!condition) {
        return null;
    }

    const expr = stripQuotedStringsForIfCheck(condition);
    const scopeStack = [createIfOperatorScope()];
    const operators = [];

    for (let i = 0; i < expr.length; i++) {
        const ch = expr[i];

        if (ch === '(') {
            scopeStack.push(createIfOperatorScope());
            continue;
        }
        if (ch === ')') {
            if (scopeStack.length > 1) {
                const closedScopeError = validateIfOperatorScope(scopeStack[scopeStack.length - 1]);
                if (closedScopeError) {
                    return closedScopeError;
                }
                scopeStack.pop();
            }
            continue;
        }

        if (ch === '&' && expr[i + 1] === '&') {
            operators.push({ kind: 'and', style: 'symbol' });
            recordIfLogicalOperator(scopeStack[scopeStack.length - 1], 'and');
            i++;
            continue;
        }
        if (ch === '|' && expr[i + 1] === '|') {
            operators.push({ kind: 'or', style: 'symbol' });
            recordIfLogicalOperator(scopeStack[scopeStack.length - 1], 'or');
            i++;
            continue;
        }

        const remainder = expr.slice(i);
        const andMatch = remainder.match(/^\s+and\b/i);
        if (andMatch) {
            operators.push({ kind: 'and', style: 'word' });
            recordIfLogicalOperator(scopeStack[scopeStack.length - 1], 'and');
            i += andMatch[0].length - 1;
            continue;
        }

        const orMatch = remainder.match(/^\s+or\b/i);
        if (orMatch) {
            operators.push({ kind: 'or', style: 'word' });
            recordIfLogicalOperator(scopeStack[scopeStack.length - 1], 'or');
            i += orMatch[0].length - 1;
        }
    }

    if (operators.length === 0) {
        return null;
    }

    const hasWordStyle = operators.some(op => op.style === 'word');
    const hasSymbolStyle = operators.some(op => op.style === 'symbol');
    if (hasWordStyle && hasSymbolStyle) {
        return 'If condition must not mix word operators (and/or) with symbol operators (&&/||). Use one style consistently or add parentheses.';
    }

    for (let s = scopeStack.length - 1; s >= 1; s--) {
        const unclosedScopeError = validateIfOperatorScope(scopeStack[s]);
        if (unclosedScopeError) {
            return unclosedScopeError;
        }
    }

    return validateIfOperatorScope(scopeStack[0]);
}

function hasDanglingIfLogicalOperator(condition) {
    if (!condition) {
        return false;
    }
    return /\s+(and|or|&&|\|\|)\s*$/i.test(stripQuotedStringsForIfCheck(condition));
}

function hasLeadingIfLogicalOperator(condition) {
    if (!condition) {
        return false;
    }
    const expr = stripQuotedStringsForIfCheck(condition).trim();
    return /^(and|or)\b/i.test(expr) || /^(&&|\|\|)/.test(expr);
}

function getIfLeadingLogicalOperatorError(condition) {
    if (hasLeadingIfLogicalOperator(condition)) {
        return 'Logical operator must not appear directly after if without a preceding condition.';
    }
    return null;
}

function getIfContinuationLinePlacementError(trimmedLine) {
    if (/^\s*(and|or)\b\s*then\b/i.test(trimmedLine) || /^\s*(&&|\|\|)\s*then\b/i.test(trimmedLine)) {
        return 'Logical operator must not appear directly before then without a condition.';
    }
    if (/^\s*(and|or)\s*$/i.test(trimmedLine) || /^\s*(&&|\|\|)\s*$/i.test(trimmedLine)) {
        return 'Logical and/or continuation line must include a condition after the operator.';
    }
    if (/^\s*(and|or)\b/i.test(trimmedLine) && !/^\s*(and|or)\b\s+.+/i.test(trimmedLine)) {
        return 'Logical and/or continuation line must include a condition after the operator.';
    }
    if (/^\s*(&&|\|\|)/i.test(trimmedLine) && !/^\s*(&&|\|\|)\s*.+/i.test(trimmedLine)) {
        return 'Logical and/or continuation line must include a condition after the operator.';
    }
    return null;
}

function getIfLogicalOperatorPlacementError(line, isPendingIfHeader) {
    const trimmed = stripValidationComment(line).trim();
    if (!trimmed) {
        return null;
    }

    const ifCondition = extractIfConditionFromLine(line);
    if (ifCondition) {
        const leadingError = getIfLeadingLogicalOperatorError(ifCondition);
        if (leadingError) {
            return leadingError;
        }
        if (hasDanglingIfLogicalOperator(ifCondition)) {
            return 'Logical operator must not appear directly before then without a condition.';
        }
    }

    if (/^\s*if\b/i.test(trimmed) && !/\bthen\b/i.test(trimmed)) {
        const afterIfMatch = trimmed.match(/^\s*if\s+/i);
        if (afterIfMatch) {
            const afterIf = trimmed.slice(afterIfMatch[0].length);
            const leadingError = getIfLeadingLogicalOperatorError(afterIf);
            if (leadingError) {
                return leadingError;
            }
            if (hasDanglingIfLogicalOperator(afterIf)) {
                return 'Logical operator at end of if line must continue on the next line with and/or.';
            }
        }
    }

    if (isPendingIfHeader && (/^\s*(and|or)\b/i.test(trimmed) || /^\s*(&&|\|\|)/.test(trimmed))) {
        return getIfContinuationLinePlacementError(trimmed);
    }

    return null;
}

function advancePendingIfHeaderState(trimmedLine, currentPendingIfHeader) {
    if (/^\s*endif\b/i.test(trimmedLine) || /^\s*else\b/i.test(trimmedLine)) {
        return false;
    }

    const hasIf = /^\s*if\b/i.test(trimmedLine);
    const hasThen = /\bthen\b/i.test(trimmedLine);

    if (hasIf && !hasThen) {
        return true;
    }

    if (hasThen && currentPendingIfHeader) {
        return false;
    }

    if (currentPendingIfHeader) {
        if (/^\s*(and|or)\b/i.test(trimmedLine) || /^\s*(&&|\|\|)/.test(trimmedLine)) {
            return true;
        }
        return false;
    }

    return false;
}

function addIfConditionExpressionRefs(conditionText, line, references) {
    if (!conditionText) {
        return;
    }
    const expressionRefs = extractVariableReferencesFromExpression(conditionText);
    for (let i = 0; i < expressionRefs.length; i++) {
        const variableName = expressionRefs[i];
        if (!shouldSkipUnusedVariableReference(variableName, line)) {
            references.add(variableName);
        }
    }
}

function collectIfConditionReferences(line, isPendingIfHeader) {
    const references = new Set();
    const trimmed = stripValidationComment(line).trim();
    if (!trimmed) {
        return references;
    }

    const ifCondition = extractIfConditionFromLine(line);
    if (ifCondition) {
        addIfConditionExpressionRefs(ifCondition, line, references);
        return references;
    }

    if (/^\s*if\b/i.test(trimmed) && !/\bthen\b/i.test(trimmed)) {
        const afterIfMatch = trimmed.match(/^\s*if\s+/i);
        if (afterIfMatch) {
            addIfConditionExpressionRefs(trimmed.slice(afterIfMatch[0].length), line, references);
        }
        return references;
    }

    if (isPendingIfHeader && (/^\s*(and|or)\b/i.test(trimmed) || /^\s*(&&|\|\|)/.test(trimmed))) {
        addIfConditionExpressionRefs(trimmed, line, references);
    }

    return references;
}

function hasIfThenExitFailsafe(lines, fromLine, beforeLine) {
    for (let i = fromLine; i < beforeLine; i++) {
        const code = getCodeLine(lines[i]);
        if (!code) {
            continue;
        }

        if (/\bif\b/i.test(code) && /\bthen\b/i.test(code) && !/\bthen\s+exit\b/i.test(code)) {
            let hasReturn = false;
            for (let j = i + 1; j < beforeLine; j++) {
                const inner = getCodeLine(lines[j]);
                if (!inner) {
                    continue;
                }
                if (/^\s*endif\b/i.test(inner)) {
                    break;
                }
                //check if line has set RETURN "1" or set RETURN "0"
                if (inner.includes('set') && inner.includes('RETURN') && (inner.includes('"1"') || inner.includes('"0"'))) {
                    hasReturn = true;
                }
                if (hasReturn && /^\s*exit\b/i.test(inner)) {
                    return true;
                }   
            }
        }
    }
    return false;
}

