const VECTOR_VARIABLE_TYPES = new Set([
    'pvector', 'dvector', 'xvector', 'yvector', 'zvector', 'nvector'
]);

function isVectorVariableType(type) {
    return typeof type === 'string' && VECTOR_VARIABLE_TYPES.has(type.toLowerCase());
}

function isValueVariableType(type) {
    return typeof type === 'string' && type.toLowerCase() === 'value';
}

function findVectorToValueTypeTransitionWarnings(lines) {
    const warnings = [];
    const fileSections = parseFileSections(lines);

    for (const [varName, typeInfos] of variableTypesByName) {
        const scopeState = new Map();

        for (let i = 0; i < typeInfos.length; i++) {
            const typeInfo = typeInfos[i];
            const sectionName = getSectionForLine(typeInfo.line, fileSections);

            if (isVerificationIgnoredSectionName(sectionName)) {
                continue;
            }

            if (!scopeState.has(sectionName)) {
                scopeState.set(sectionName, {
                    hadVectorType: false,
                    firstVectorEntry: null
                });
            }
            const state = scopeState.get(sectionName);

            if (isVectorVariableType(typeInfo.type)) {
                if (!state.hadVectorType) {
                    state.hadVectorType = true;
                    state.firstVectorEntry = typeInfo;
                }
            }
            else if (state.hadVectorType && isValueVariableType(typeInfo.type)) {
                warnings.push({
                    varName,
                    line: typeInfo.line,
                    sectionName,
                    firstVectorEntry: state.firstVectorEntry
                });
            }
        }
    }

    return warnings;
}

function checkVectorToValueTypeTransitions(lines, textDocument, lineOffsets) {
    const diagnostics = [];
    const warnings = findVectorToValueTypeTransitionWarnings(lines);

    for (let i = 0; i < warnings.length; i++) {
        const warning = warnings[i];
        const lineText = lines[warning.line] || '';
        const vectorType = warning.firstVectorEntry.type;
        const sectionSuffix = warning.sectionName ? ` in section ${warning.sectionName}` : '';
        const message = `Variable ${warning.varName} was previously typed as ${vectorType}${sectionSuffix} and is now typed as value.`;
        const diagnostic = reportProblem123(warning.line, lineText, message, lines, textDocument, lineOffsets);

        if (hasDiagnosticRelatedInformationCapability && warning.firstVectorEntry) {
            const vectorLine = warning.firstVectorEntry.line;
            const vectorLineText = lines[vectorLine] || '';
            const vectorOffset = typeof lineOffsets?.[vectorLine] === 'number'
                ? lineOffsets[vectorLine]
                : lines.slice(0, vectorLine).join('\n').length;
            diagnostic.relatedInformation = [{
                location: {
                    uri: textDocument.uri,
                    range: {
                        start: textDocument.positionAt(vectorOffset + 1),
                        end: textDocument.positionAt(vectorOffset + vectorLineText.length)
                    }
                },
                message: `First typed as ${vectorType} here`
            }];
        }

        diagnostics.push(diagnostic);
    }

    return diagnostics;
}

function reportProblem123(lineNumber, lineText, message, lines, textDocument, lineOffsets) {
    let offset = typeof lineOffsets?.[lineNumber] === 'number'
        ? lineOffsets[lineNumber]
        : lines.slice(0, lineNumber).join('\n').length;
    const diagnostic = {
        severity: node_1.DiagnosticSeverity.Warning,
        range: {
            start: textDocument.positionAt(offset+1),
            end: textDocument.positionAt(offset + lineText.length)
        },
        message: `${lineText} has an error: ${message}`,
        source: 'ADT-Syntax'
    };
    if (hasDiagnosticRelatedInformationCapability) {
        diagnostic.relatedInformation = [
            {
                location: {
                    uri: textDocument.uri,
                    range: Object.assign({}, diagnostic.range)
                },
                message: message
            }
        ];
    }
    return(diagnostic)

}

