function makeUnusedVariableKey(sectionName, varName) {
    return `${sectionName || ''}::${varName}`;
}

function getIfConditionTextSpans(splitline, line, isPendingIfHeader) {
    const spans = [];
    const trimmed = stripValidationComment(line).trim();
    if (!trimmed) {
        return spans;
    }

    const ifCondition = extractIfConditionFromLine(line);
    if (ifCondition) {
        const conditionIndex = splitline.indexOf(ifCondition);
        if (conditionIndex !== -1) {
            spans.push({ start: conditionIndex, end: conditionIndex + ifCondition.length });
        }
        return spans;
    }

    if (/^\s*if\b/i.test(trimmed) && !/\bthen\b/i.test(trimmed)) {
        const afterIfMatch = trimmed.match(/^\s*if\s+/i);
        if (afterIfMatch) {
            const afterIf = trimmed.slice(afterIfMatch[0].length);
            const afterIfIndex = splitline.indexOf(afterIf);
            if (afterIfIndex !== -1) {
                spans.push({ start: afterIfIndex, end: afterIfIndex + afterIf.length });
            }
        }
        return spans;
    }

    if (isPendingIfHeader && (/^\s*(and|or)\b/i.test(trimmed) || /^\s*(&&|\|\|)/.test(trimmed))) {
        spans.push({ start: 0, end: splitline.length });
    }

    return spans;
}

function isIndexInsideIfConditionSpans(index, spans) {
    for (let i = 0; i < spans.length; i++) {
        if (index >= spans[i].start && index < spans[i].end) {
            return true;
        }
    }
    return false;
}

function parseDeclarationVariablesFromSplitLine(splitline, line, isPendingIfHeader) {
    const names = new Set();
    if (!splitline || splitline.trim().startsWith('!')) {
        return names;
    }

    const conditionSpans = getIfConditionTextSpans(splitline, line, isPendingIfHeader);
    const assignmentPattern = /\b[A-Za-z][A-Za-z0-9_-]*\b(?=\s*=(?!=))/g;
    let match;

    while ((match = assignmentPattern.exec(splitline)) !== null) {
        const varName = match[0];
        if (keywordLabelsSet.has(varName)) {
            continue;
        }
        if (isIndexInsideIfConditionSpans(match.index, conditionSpans)) {
            continue;
        }
        names.add(varName);
    }

    return names;
}

function shouldSkipUnusedVariableReference(variableName, line) {
    if (keywordLabelsSet.has(variableName)) {
        return true;
    }
    if (variableName === 'SHEETORIG' || variableName === 'AREAORIG') {
        return true;
    }
    const variableIndex = line.indexOf(variableName);
    const firstHashIndex = line.indexOf('#');
    const lastHashIndex = line.lastIndexOf('#');
    if (firstHashIndex !== -1 && lastHashIndex !== -1 && firstHashIndex < variableIndex && variableIndex < lastHashIndex) {
        return true;
    }
    return false;
}

function stripCallSegmentsForUnusedReferenceScan(codeLine) {
    return codeLine.replace(/call\s*\([^)]*\)/gi, 'call()');
}

function collectReferencesFromValidationLine(codeLine, line, isPendingIfHeader) {
    const references = new Set();
    const expressionRefs = extractVariableReferencesFromExpression(
        stripCallSegmentsForUnusedReferenceScan(codeLine)
    );
    for (let i = 0; i < expressionRefs.length; i++) {
        const variableName = expressionRefs[i];
        if (!shouldSkipUnusedVariableReference(variableName, line)) {
            references.add(variableName);
        }
    }
    const ifConditionRefs = collectIfConditionReferences(line, !!isPendingIfHeader);
    ifConditionRefs.forEach((variableName) => references.add(variableName));
    return references;
}

function loadLinkedFileText(targetPath) {
    const normalizedTarget = normalizeFsPath(targetPath);
    if (!normalizedTarget) {
        return null;
    }

    for (const doc of documents.all()) {
        if (normalizeFsPath(uriToFsPath(doc.uri)) === normalizedTarget) {
            return doc.getText();
        }
    }

    try {
        if (fs.existsSync(targetPath)) {
            return fs.readFileSync(targetPath, 'utf8');
        }
    } catch (_error) {
        return null;
    }
    return null;
}

function scanFileForVariableReferences(fileContent, targetNames, fileSections, options) {
    const found = new Set();
    if (!fileContent || !targetNames || targetNames.size === 0) {
        return found;
    }

    const restrictToSection = options && options.restrictToSection !== undefined
        ? options.restrictToSection
        : null;
    const lines = fileContent.split('\n');
    const sections = fileSections || parseFileSections(lines);
    let pendingIfHeader = false;

    for (let i = 0; i < lines.length; i++) {
        const originalTrimmedLine = lines[i].trim();
        if (originalTrimmedLine.startsWith('!')) {
            continue;
        }
        if (originalTrimmedLine.startsWith('##')) {
            continue;
        }
        if (originalTrimmedLine.length === 0) {
            continue;
        }
        if (restrictToSection !== null && getSectionForLine(i, sections) !== restrictToSection) {
            continue;
        }

        let line = lines[i];
        line = stripValidationComment(line);
        const bangCommentIndex = findInlineBangCommentIndex(line);
        const codeLine = bangCommentIndex === -1 ? line : line.slice(0, bangCommentIndex);
        const trimmedLine = stripValidationComment(line).trim();
        const refs = collectReferencesFromValidationLine(codeLine, line, pendingIfHeader);
        refs.forEach((variableName) => {
            if (targetNames.has(variableName)) {
                found.add(variableName);
            }
        });
        pendingIfHeader = advancePendingIfHeaderState(trimmedLine, pendingIfHeader);
    }

    return found;
}

function collectUnusedVariableDiagnostics(lines, textDocument, lineOffsets, fileSections, filePath) {
    const declarations = new Map();
    const usageCounts = new Map();

    function ensureDeclaration(sectionName, varName, lineIndex, lineText) {
        const key = makeUnusedVariableKey(sectionName, varName);
        if (!declarations.has(key)) {
            declarations.set(key, {
                sectionName: sectionName || '',
                varName,
                lineIndex,
                lineText,
            });
            usageCounts.set(key, 0);
        }
    }

    function incrementUsage(sectionName, varName) {
        const key = makeUnusedVariableKey(sectionName, varName);
        if (declarations.has(key)) {
            usageCounts.set(key, (usageCounts.get(key) || 0) + 1);
        }
    }

    let pendingIfHeader = false;

    for (let i = 0; i < lines.length; i++) {
        let line = lines[i];
        const originalTrimmedLine = line.trim();
        if (originalTrimmedLine.startsWith('!')) {
            continue;
        }
        if (originalTrimmedLine.startsWith('##') && !originalTrimmedLine.startsWith('##included_from')) {
            continue;
        }
        if (originalTrimmedLine.length === 0) {
            continue;
        }
        line = stripValidationComment(line);

        const sectionName = getSectionForLine(i, fileSections);
        if (isLineInVerificationIgnoredSection(i, fileSections)) {
            const trimmedLine = stripValidationComment(line).trim();
            pendingIfHeader = advancePendingIfHeaderState(trimmedLine, pendingIfHeader);
            continue;
        }
        const bangCommentIndex = findInlineBangCommentIndex(line);
        const codeLine = bangCommentIndex === -1 ? line : line.slice(0, bangCommentIndex);
        const trimmedLine = stripValidationComment(line).trim();
        const splitlines = line.split(';');
        const declarationNamesOnLine = new Set();

        for (let j = 0; j < splitlines.length; j++) {
            const declarationVars = parseDeclarationVariablesFromSplitLine(splitlines[j], line, pendingIfHeader);
            declarationVars.forEach((varName) => {
                ensureDeclaration(sectionName, varName, i, line);
                declarationNamesOnLine.add(varName);
            });
        }

        const refs = collectReferencesFromValidationLine(codeLine, line, pendingIfHeader);
        declarationNamesOnLine.forEach((declName) => refs.delete(declName));
        refs.forEach((varName) => incrementUsage(sectionName, varName));
        pendingIfHeader = advancePendingIfHeaderState(trimmedLine, pendingIfHeader);
    }

    for (let i = 0; i < lines.length; i++) {
        const trimmed = lines[i].trim();
        if (!trimmed.startsWith('##included_from')) {
            continue;
        }
        const match = lines[i].match(/##included_from\s+(.+?)$/i);
        if (!match) {
            continue;
        }

        const sectionName = getSectionForLine(i, fileSections);
        const resolvedPath = resolveVertexFilePath(match[1].trim());
        if (!resolvedPath) {
            continue;
        }

        const includedText = loadLinkedFileText(resolvedPath);
        if (!includedText) {
            continue;
        }

        const includedVars = extractVariablesFromIncludedFile(includedText);
        const includedNames = new Set();
        for (let v = 0; v < includedVars.variables.length; v++) {
            includedNames.add(includedVars.variables[v].name);
            ensureDeclaration(sectionName, includedVars.variables[v].name, i, lines[i]);
        }
        for (let v = 0; v < includedVars.stringVariables.length; v++) {
            includedNames.add(includedVars.stringVariables[v].name);
            ensureDeclaration(sectionName, includedVars.stringVariables[v].name, i, lines[i]);
        }

        const foundInIncluded = scanFileForVariableReferences(
            includedText,
            includedNames,
            parseFileSections(includedText.split('\n'))
        );
        foundInIncluded.forEach((varName) => incrementUsage(sectionName, varName));
    }

    const normalizedPath = normalizeFsPath(filePath);
    const entry = workspaceDeclarationIndex.get(normalizedPath);
    if (entry) {
        for (let i = 0; i < (entry.includeLinks || []).length; i++) {
            const link = entry.includeLinks[i];
            const sourceSection = link.sourceSection || '';
            const targetText = loadLinkedFileText(link.targetPath);
            if (!targetText) {
                continue;
            }
            const targetSections = parseFileSections(targetText.split('\n'));
            const scanOptions = link.targetSection
                ? { restrictToSection: link.targetSection }
                : undefined;

            declarations.forEach((decl, key) => {
                if (decl.sectionName !== sourceSection) {
                    return;
                }
                const found = scanFileForVariableReferences(
                    targetText,
                    new Set([decl.varName]),
                    targetSections,
                    scanOptions
                );
                if (found.has(decl.varName)) {
                    usageCounts.set(key, (usageCounts.get(key) || 0) + 1);
                }
            });
        }

        if (entry.commonIndexes || entry.commonPoints) {
            for (let i = 0; i < (entry.callLinks || []).length; i++) {
                const link = entry.callLinks[i];
                const sourceSection = link.sourceSection || '';
                const callLine = lines[link.line];
                if (!callLine) {
                    continue;
                }

                let line = callLine;
                line = stripValidationComment(line);
                const bangCommentIndex = findInlineBangCommentIndex(line);
                const codeLine = bangCommentIndex === -1 ? line : line.slice(0, bangCommentIndex);
                const callArgs = getCallCommandVariableReferences(codeLine);
                const declaredArgs = callArgs.filter((argName) =>
                    declarations.has(makeUnusedVariableKey(sourceSection, argName))
                );
                if (declaredArgs.length === 0) {
                    continue;
                }

                const targetText = loadLinkedFileText(link.targetPath);
                if (!targetText) {
                    continue;
                }
                const foundInCallee = scanFileForVariableReferences(
                    targetText,
                    new Set(declaredArgs),
                    parseFileSections(targetText.split('\n'))
                );
                for (let a = 0; a < declaredArgs.length; a++) {
                    if (foundInCallee.has(declaredArgs[a])) {
                        incrementUsage(sourceSection, declaredArgs[a]);
                    }
                }
            }
        }
    }

    const diagnostics = [];
    declarations.forEach((decl, key) => {
        if ((usageCounts.get(key) || 0) === 0) {
            diagnostics.push(reportProblem4(
                decl.lineIndex,
                decl.lineText,
                `Variable ${decl.varName} is declared but not used.`,
                lines,
                textDocument,
                lineOffsets
            ));
        }
    });
    return diagnostics;
}

function reportProblem4(lineNumber, lineText, message, lines, textDocument, lineOffsets) {
    let offset = typeof lineOffsets?.[lineNumber] === 'number'
        ? lineOffsets[lineNumber]
        : lines.slice(0, lineNumber).join('\n').length;
    const diagnostic = {
        severity: node_1.DiagnosticSeverity.Information,
        range: {
            start: textDocument.positionAt(offset+1),
            end: textDocument.positionAt(offset + lineText.length)
        },
        message: `${lineText} has an error: ${message}`,
        source: 'ADT-Syntax'
    };
    if (hasDiagnosticRelatedInformationCapability) {
        diagnostic.relatedInformation = [
            {
                location: {
                    uri: textDocument.uri,
                    range: Object.assign({}, diagnostic.range)
                },
                message: message
            }
        ];
    }
    return diagnostic;
}

function variableTypeCollection(lines) {

    console.time('Variable Type Collection Scan');

    console.time('filesection read')
    const fileSections = parseFileSections(lines);
    console.timeEnd('filesection read')
    for (let i = 0; i < lines.length; i++) {

        let line = lines[i];
        const trimmedLine = line.trim();
        //ignore lines that contain IGNORE TYPE
        if (trimmedLine.includes('IGNORE TYPE')) {
            continue;
        }
        //ignore anything after ;!
        line = stripValidationComment(line);

        // Handle ##included_from directive
        if (trimmedLine.startsWith('##included_from')) {
            handleIncludedFile(line, i, fileSections);
            continue;
        }
        //ignore whole line if it starts with !
        if (trimmedLine.startsWith('!')) {
            continue;
        }
        //ignore line if it starts with # include
        if (trimmedLine.startsWith('#include')) {
            continue;
        }
        //ignore line if it starts with ##included_from
        if (trimmedLine.startsWith('##included_from')) {
            continue;
        }
        //ignore line if it starts with #
        if (trimmedLine.startsWith('#')) {
            continue;
        }

        //ignore line if it ends with ##
        if (trimmedLine.endsWith('##')) {
            continue;
        }
        //ignore line if it starts with call
        if (trimmedLine.startsWith('call ')) {
            continue;
        }

        //ignore line if it starts with debug
        if (trimmedLine.startsWith('debug ')) {
            continue;
        }

        analyzeLineForVariableTypes(line, i, variableTypes, fileSections);

        let match = null;

        while ((match = variableRegex.exec(line)) !== null) {
            const varName = match[1];
            const startChar = match.index;

            // Skip if inside quotes, keywords, or vector patterns (existing logic)
            if (isInsideQuotes(line, startChar) || 
                keywordLabelsSet.has(varName) ||
                (!globalSettings.strictMode && /[PXYZN](\d+)?$/.test(varName))) {
                continue;
            }
            //handle comment assignments by checking for varName in hovervariablesMap and retrieving [] content from there.
            if (hovervariablesMap.has(varName)) {
                const hoverInfo = hovervariablesMap.get(varName);
                if (hoverInfo) {
                    const bracketMatch = hoverInfo.match(/\[(.*?)\]/);
                    const bracketContent = bracketMatch ? bracketMatch[1].trim().toLowerCase() : null;
                    if (bracketContent) {
                        //direct translation
                        pushVariableTypeEntry(variableTypes, varName, bracketContent, i, getSectionForLine(i, fileSections));
                        continue;
                    }
                }
            }
        }
    }
    console.timeEnd('Variable Type Collection Scan');
    // After populating variableTypes array, build the map for faster lookups
    console.time('Variable Type Map Build');
    variableTypesByName.clear();
    for (const typeInfo of variableTypes) {
        if (!variableTypesByName.has(typeInfo.name)) {
            variableTypesByName.set(typeInfo.name, []);
        }
        variableTypesByName.get(typeInfo.name).push(typeInfo);
    }
    console.timeEnd('Variable Type Map Build');
    
    // Sort each variable's type entries by line number for faster lookup
    console.time('Variable Type Map Sort');
    for (const typeInfos of variableTypesByName.values()) {
        typeInfos.sort((a, b) => a.line - b.line);
    }
    console.timeEnd('Variable Type Map Sort');
}

// Add this helper function before the getVariableType function (around line 13980)
function extractBaseVariableName(variableName) {
    // Remove whitespace
    variableName = variableName.trim();
    
    // If it's already a simple variable name, return as-is
    if (/^[A-Za-z][A-Za-z0-9_-]*\$?$/.test(variableName)) {
        return variableName;
    }
    
    // Handle mathematical expressions like shtP+2, varName-1, etc.
    // Look for base variable name followed by mathematical operators
    const mathExprMatch = variableName.match(/^([A-Za-z][A-Za-z0-9_-]*\$?)[\+\-\*\/]\d+/);
    if (mathExprMatch) {
        return mathExprMatch[1];
    }
    
    // Handle array indexing and string slices: varName[0], filename$[1,3], Code$[i,i]
    const arrayIndexMatch = variableName.match(/^([A-Za-z][A-Za-z0-9_-]*\$?)\[[^\]]+\]/);
    if (arrayIndexMatch) {
        return arrayIndexMatch[1];
    }
    
    // Handle more complex expressions - extract the first valid variable name
    const firstVarMatch = variableName.match(/^([A-Za-z][A-Za-z0-9_-]*\$?)/);
    if (firstVarMatch) {
        return firstVarMatch[1];
    }
    
    // If no pattern matches, return the original
    return variableName;
}

// Helper function to check if a character is a math operator
function isMathOperator(char) {
    return ['+', '-', '*', '/'].includes(char);
}

// Helper function to check if we're starting a new parameter (not continuing a math expression)
function isStartOfNewParam(str) {
    // Check if it starts with a variable name, function call, or quoted string
    return /^[a-zA-Z_]|^"/.test(str);
}

// Helper function to check if we're at the end of a parameter (not in the middle of a math expression)
function isEndOfParam(str) {
    // Check if it ends with a complete token (variable, number, or closing paren/quote)
    return /[a-zA-Z0-9_)\]"]$/.test(str);
}

function getVecToReturnType(params) {
    // Check if we have exactly 3 parameters after the output parameter
    if (params.length >= 4) {
        const x = params[1]?.trim();
        const y = params[2]?.trim();
        const z = params[3]?.trim();
        
        // Check for specific vector patterns
        if (x === '1' && y === '0' && z === '0') {
            return 'xvector';
        } else if (x === '0' && y === '1' && z === '0') {
            return 'yvector';
        } else if (x === '0' && y === '0' && z === '1') {
            return 'zvector';
        }
    }
    
    // Default to pvector for all other cases
    return 'pvector';
}

function getVariableType2(variableName, lineNumber, sectionName) {
    const targetSection = sectionName ?? '';
    // Look through the variableTypes array to find the most recent type declaration for this variable
    let mostRecentType = 'generic'; // default fallback
    let mostRecentLine = -1;
    
    for (const varType of variableTypes) {
        if (varType.name === variableName &&
            varType.line < lineNumber &&
            (varType.sectionName ?? '') === targetSection &&
            varType.line >= mostRecentLine) {
            mostRecentType = varType.type;
            mostRecentLine = varType.line;
        }
    }
    //replace vartype in variabletypes with mostRecentType

    return mostRecentType;
}
function isValidCommand(expr) {
    // Trim the expression
    expr = expr.trim();
    if (!expr) return false;
    
    // Check if it matches a command pattern (functionName(...))
    const commandMatch = expr.match(/^(\w+)\s*\(/);
    if (!commandMatch) return false;
    
    const functionName = commandMatch[1].toLowerCase();
    
    // Check if it's a known command
    if (commandValidations.hasOwnProperty(functionName)) {
        return true;
    }
    
    // Check if it's in other function maps
    if (returnTypeMap.hasOwnProperty(functionName) || 
        inputParamTypeMap.hasOwnProperty(functionName)) {
        return true;
    }
    
    return false;
}

// Add a function to check if expression is valid as either variable, command, or math expression
function isValidVariableOrCommand(expr) {
    // Check if it's a valid variable
    if (isValidNormalVariable(expr)) {
        return true;
    }
    
    // Check if it's a valid command
    if (isValidCommand(expr)) {
        return true;
    }
    
    // Check if it's a math expression that might contain commands
    if (isValidMathExpressionWithCommands(expr)) {
        return true;
    }
    
    return false;
}

// Enhanced math expression validator that handles commands
function isValidMathExpressionWithCommands(expr) {
    expr = expr.trim();
    if (!expr) return false;
    
    // Handle parentheses by recursively validating sub-expressions
    let parenStack = [];
    let i = 0;
    
    while (i < expr.length) {
        const char = expr[i];
        
        if (char === '(') {
            // Check if this is part of a function call
            let beforeParen = '';
            let j = i - 1;
            while (j >= 0 && /[a-zA-Z_]/.test(expr[j])) {
                beforeParen = expr[j] + beforeParen;
                j--;
            }
            
            if (beforeParen && isValidCommand(beforeParen + expr.substring(i))) {
                // Skip the entire function call
                let parenCount = 1;
                i++;
                while (i < expr.length && parenCount > 0) {
                    if (expr[i] === '(') parenCount++;
                    if (expr[i] === ')') parenCount--;
                    i++;
                }
                continue;
            } else {
                parenStack.push(i);
                i++;
            }
        } else if (char === ')') {
            if (parenStack.length === 0) {
                return false; // Unmatched closing parenthesis
            }
            
            const openIndex = parenStack.pop();
            const subExpr = expr.substring(openIndex + 1, i);
            
            // Recursively validate the sub-expression
            if (!isValidMathExpressionWithCommands(subExpr)) {
                return false;
            }
            
            // Replace with placeholder
            const beforeParen = expr.substring(0, openIndex);
            const afterParen = expr.substring(i + 1);
            expr = beforeParen + 'VALID_SUBEXPR' + afterParen;
            i = openIndex + 'VALID_SUBEXPR'.length;
        } else {
            i++;
        }
    }
    
    if (parenStack.length > 0) {
        return false; // Unmatched opening parentheses
    }
    
    // Now validate the expression without nested parentheses
    return isValidFlatMathExpressionWithCommands(expr);
}

function isValidFlatMathExpressionWithCommands(expr) {
    // Remove spaces for easier processing
    expr = expr.replace(/\s+/g, '');
    
    if (!expr) return false;
    
    // Split by operators while preserving the operators
    const tokens = expr.split(/([+\-*/])/).filter(token => token !== '');
    
    if (tokens.length === 0) return false;
    
    // Check if we have alternating operands and operators
    for (let i = 0; i < tokens.length; i++) {
        if (i % 2 === 0) {
            // Even indices should be operands (variables, numbers, or commands)
            if (!isValidMathOperandWithCommands(tokens[i])) {
                return false;
            }
        } else {
            // Odd indices should be operators
            if (!/^[+\-*/]$/.test(tokens[i])) {
                return false;
            }
        }
    }
    
    // Must start and end with operands
    return tokens.length % 2 === 1;
}

function isValidMathOperandWithCommands(operand) {
    operand = operand.trim();
    if (!operand) return false;
    
    // Check if it's a number
    if (/^-?\d+(\.\d+)?$/.test(operand)) {
        return true;
    }
    
    // Check if it's our placeholder
    if (operand === 'VALID_SUBEXPR') {
        return true;
    }
    
    // Check if it's a valid command
    if (isValidCommand(operand)) {
        return true;
    }
    
    // Check if it's a valid variable
    if (VARIABLE_PATTERNS.BASIC_VAR.test(operand)) {
        return true;
    }
    
    // Check if it's a ticker expression
    const tickerMatch = operand.match(VARIABLE_PATTERNS.TICKER);
    if (tickerMatch) {
        const baseVar = tickerMatch[1];
        const tickerContent = tickerMatch[2];
        
        if (!VARIABLE_PATTERNS.BASIC_VAR.test(baseVar)) {
            return false;
        }
        
        // Ticker content can be a variable, number, or command
        return isValidMathOperandWithCommands(tickerContent);
    }
    
    return false;
}

// Add new function to handle included files
function handleIncludedFile(line, lineNumber, fileSections) {
    // Extract filename from ##included_from directive
    const match = line.match(/##included_from\s+(.+?)$/i);
    if (!match) return;
    
    const fileName = match[1].trim();
    const filePath = findFile(fileName);
    
    if (!filePath) return;

    const sectionName = fileSections
        ? getSectionForLine(lineNumber, fileSections)
        : '';
    
    try {
        if (!fs.existsSync(filePath)) return;
        
        const fileContent = fs.readFileSync(filePath, 'utf8');
        const includedVariables = extractVariablesFromIncludedFile(fileContent);
        
        // Add all variables from included file as if they were declared on this line
        for (const variable of includedVariables.variables) {
            // Add to hovervariables for semantic highlighting
            hovervariables.push({
                name: variable.name,
                type: variable.type || detectObjectType(variable.name, []),
                line: lineNumber,
                hover: variable.hover || `Variable from included file: ${fileName}`,
                length: variable.name.length
            });
            
            // Add type information
            pushVariableTypeEntry(
                variableTypes,
                variable.name,
                variable.type || detectObjectType(variable.name, []),
                lineNumber,
                sectionName
            );
        }
        
        // Handle string variables
        for (const stringVariable of includedVariables.stringVariables) {
            hoverstringvariables.push({
                name: stringVariable.name,
                type: 'string',
                line: lineNumber,
                hover: stringVariable.hover || `String variable from included file: ${fileName}`,
                length: stringVariable.name.length
            });
            
            pushVariableTypeEntry(variableTypes, stringVariable.name, 'string', lineNumber, sectionName);
        }
        
    } catch (error) {
        console.error(`Error reading included file ${filePath}:`, error);
    }
}

// Add function to extract variables and their types from included files
function extractVariablesFromIncludedFile(fileContent) {
    const extractedVariables = [];
    const extractedStringVariables = [];
    const lines = fileContent.split('\n');
    
    // Temporary storage for analyzing types in the included file
    const tempVariableTypes = [];
    
    for (let i = 0; i < lines.length; i++) {
        let line = lines[i];
        
        // Skip comments and preprocessor directives
        if (line.trim().startsWith('!') || line.trim().startsWith('#')) {
            continue;
        }

        const hoverPattern = /;\s*!"([^"]*)"/;
        const hoverMatch = line.match(hoverPattern);
        const hoverText = hoverMatch ? hoverMatch[1] : null;

        // Remove inline comments
        line = stripValidationComment(line);
        
        // Extract variable declarations
        const variablePattern1 = /\b([A-Za-z][A-Za-z0-9_-]*)\$(?=\s*=)/g;
        const variablePattern2 = /\b([A-Za-z][A-Za-z0-9_-]*)\b(?:\([^)]*\))?(?!$)(?=\s*=)/g;
        const variablePattern3 = /\bset\s+([A-Za-z][A-Za-z0-9_-]*)\b/g;
        
        let match;
        const hoverTypeMatch = hoverText ? hoverText.match(/\[(.*?)\]/) : null;
        const hoverType = hoverTypeMatch ? hoverTypeMatch[1].trim().toLowerCase() : null;
        
        // String variables
        while ((match = variablePattern1.exec(line)) !== null) {
            const varName = match[1] + '$';
            if (!extractedStringVariables.some(v => v.name === varName)) {
                extractedStringVariables.push({
                    name: varName,
                    type: 'string',
                    hover: hoverText,
                    line: i
                });
            }
        }
        
        // Regular variables
        while ((match = variablePattern2.exec(line)) !== null) {
            const varName = match[1];
            if (!extractedVariables.some(v => v.name === varName)) {
                // Determine type by analyzing the line
                const variableType = analyzeVariableTypeFromLine(line, varName, tempVariableTypes, i);
                
                extractedVariables.push({
                    name: varName,
                    type: (variableType === 'generic' && hoverType) ? hoverType : variableType,
                    hover: hoverText,
                    line: i
                });
            }
        }
        
        // Set variables
        while ((match = variablePattern3.exec(line)) !== null) {
            const varName = match[1];
            if (!extractedVariables.some(v => v.name === varName)) {
                extractedVariables.push({
                    name: varName,
                    type: 'generic',
                    hover: hoverText,
                    line: i
                });
            }
        }
        
        // Analyze function calls for type information
        analyzeLineForVariableTypesIncluded(line, i, tempVariableTypes);
    }
    
    // Apply discovered types to variables
    for (const variable of extractedVariables) {
        if (variable.type === 'generic') {
            const typeInfo = tempVariableTypes.find(t => t.name === variable.name);
            if (typeInfo) {
                variable.type = typeInfo.type;
            } else {
                variable.type = detectObjectType(variable.name, extractedVariables);
            }
        }
    }
    
    return {
        variables: extractedVariables,
        stringVariables: extractedStringVariables
    };
}

// Helper function to analyze variable types from included files
function analyzeLineForVariableTypesIncluded(line, lineNumber, tempVariableTypes) {
    const functionMatch = line.match(/(\w+)\s*\(/);
    if (!functionMatch) return;
    
    const funcName = functionMatch[1];
    
    // Check if function is in inputParamTypeMap
    if (inputParamTypeMap.hasOwnProperty(funcName.toLowerCase())) {
        const paramsMatch = line.match(/\(\s*([a-zA-Z][a-zA-Z0-9_]*)/);
        if (paramsMatch) {
            const firstParam = paramsMatch[1];
            let outputType = inputParamTypeMap[funcName.toLowerCase()];
            
            // Special handling for vec_to
            if (funcName.toLowerCase() === 'vec_to') {
                const fullLine = line.trim();
                const afterParentheses = fullLine.substring(fullLine.indexOf(')') + 1).trim();
                const allParams = afterParentheses.split(',').map(p => p.trim());
                const allParamsWithOutput = [firstParam, ...allParams];
                outputType = getVecToReturnType(allParamsWithOutput);
            }
            
            // Special handling for vec_copy
            if (funcName.toLowerCase() === 'vec_copy') {
                const fullLine = line.trim();
                const afterParentheses = fullLine.substring(fullLine.indexOf(')') + 1).trim();
                const inputParam = afterParentheses.trim().replace(/[,\s]*$/, '').trim();
                outputType = getVariableType2(inputParam, lineNumber);
            }
            
            if (outputType) {
                tempVariableTypes.push({
                    name: firstParam,
                    type: outputType,
                    line: lineNumber
                });
            }
        }
    }
    
    // Handle functions that modify multiple specific parameters
    const multiParamTypes = multiParamTypeMap[funcName.toLowerCase()];
    if (multiParamTypes) {
        const fullParamsMatch = line.match(/\(([^)]+)\)/);
        if (fullParamsMatch) {
            const params = fullParamsMatch[1].split(',').map(p => p.trim());
            
            Object.keys(multiParamTypes).forEach(position => {
                const paramIndex = parseInt(position) - 1;
                if (params[paramIndex] && /^[a-zA-Z][a-zA-Z0-9_]*$/.test(params[paramIndex])) {
                    tempVariableTypes.push({
                        name: params[paramIndex],
                        type: multiParamTypes[position],
                        line: lineNumber
                    });
                }
            });
        }
    }
    
    // Handle paramTypeMap (functions that set output parameters)
    const outputParamTypes = paramTypeMap[funcName.toLowerCase()];
    if (outputParamTypes) {
        const afterParentheses = line.substring(line.indexOf(')') + 1).trim();
        const outputParams = afterParentheses.split(',').map(p => p.trim());
        
        Object.keys(outputParamTypes).forEach(position => {
            const paramIndex = parseInt(position) - 1;
            if (outputParams[paramIndex] && /^[a-zA-Z][a-zA-Z0-9_]*$/.test(outputParams[paramIndex])) {
                tempVariableTypes.push({
                    name: outputParams[paramIndex],
                    type: outputParamTypes[position],
                    line: lineNumber
                });
            }
        });
    }
}

// Helper function to analyze variable type from assignment line
function analyzeVariableTypeFromLine(line, varName, tempVariableTypes, lineNumber) {
    // Check if it's assigned from a function with known return type
    const assignmentMatch = line.match(new RegExp(`\\b${varName}\\s*=\\s*(\\w+)\\s*\\(`));
    if (assignmentMatch) {
        const funcName = assignmentMatch[1].toLowerCase();
        if (returnTypeMap.hasOwnProperty(funcName)) {
            return returnTypeMap[funcName];
        }
    }
    
    // Check if it's assigned from another variable with known type
    const varAssignmentMatch = line.match(new RegExp(`\\b${varName}\\s*=\\s*([a-zA-Z][a-zA-Z0-9_]*)`));
    if (varAssignmentMatch) {
        const sourceVar = varAssignmentMatch[1];
        const sourceType = tempVariableTypes.find(t => t.name === sourceVar);
        if (sourceType) {
            return sourceType.type;
        }
    }
    
    return 'generic';
}

function getKeywordByLabel(label) {
    const lower = label.toLowerCase();
    return keywords.find(keyword => keyword.label.toLowerCase() === lower);
}

function extractParamsFromInsertText(insertText) {
    const insideParams = [];
    const afterParams = [];
    if (!insertText) {
        return { insideParams, afterParams };
    }

    const openIndex = insertText.indexOf('(');
    if (openIndex === -1) {
        return { insideParams, afterParams };
    }
    let closeIndex = -1;
    let depth = 0;
    for (let i = openIndex; i < insertText.length; i++) {
        const ch = insertText[i];
        if (ch === '(') {
            depth++;
        } else if (ch === ')') {
            depth--;
            if (depth === 0) {
                closeIndex = i;
                break;
            }
        }
    }

    const placeholderRegex = /\$\{(\d+):([^}]+)\}|\$(\d+)/g;
    let match;
    while ((match = placeholderRegex.exec(insertText)) !== null) {
        const index = match.index;
        const label = match[2] || `param${match[1] || match[3]}`;
        if (index > openIndex && (closeIndex === -1 || index < closeIndex)) {
            insideParams.push(label);
        } else if (closeIndex !== -1 && index > closeIndex) {
            afterParams.push(label);
        }
    }

    return { insideParams, afterParams };
}

function buildParamLabels(commandName) {
    const keyword = getKeywordByLabel(commandName);
    if (keyword && keyword.insertText) {
        const extracted = extractParamsFromInsertText(keyword.insertText);
        if (extracted.insideParams.length || extracted.afterParams.length) {
            return extracted;
        }
    }

    const validation = commandValidations[commandName];
    const structure = validation ? validation.structure : undefined;
    const strictMode = validation ? validation.strictMode : undefined;

    const maxInside = structure && (structure.maxParamsInside ?? structure.minParamsInside) || 0;
    const maxOutside = structure && (structure.maxParamsOutside ?? structure.maxAfterParams ?? structure.paramsOutside ?? structure.afterParams) || 0;

    const insideParams = [];
    const afterParams = [];

    for (let i = 0; i < maxInside; i++) {
        const strictMatch = strictMode && strictMode.inputTypes && strictMode.inputTypes.find(param => param.paramIndex === i);
        insideParams.push(strictMatch ? strictMatch.paramName : `param${i + 1}`);
    }

    for (let i = 0; i < maxOutside; i++) {
        const strictMatch = strictMode && strictMode.afterParamTypes && strictMode.afterParamTypes.find(param => param.paramIndex === i);
        afterParams.push(strictMatch ? strictMatch.paramName : `param${i + 1}`);
    }

    return { insideParams, afterParams };
}

function getCommandContext(text, offset) {
    const lineStart = text.lastIndexOf('\n', Math.max(0, offset - 1)) + 1;
    const linePrefix = text.slice(lineStart, offset);

    const upto = linePrefix;
    const regex = /([A-Za-z][A-Za-z0-9_]*)\s*\(/g;
    let match;
    let last = null;
    while ((match = regex.exec(upto)) !== null) {
        last = {
            name: match[1],
            openParenIndex: regex.lastIndex - 1
        };
    }

    if (last && commandNamesSet.has(last.name)) {
        let depth = 1;
        let inString = null;
        let insideCommas = 0;
        let afterCommas = 0;
        let closed = false;

        for (let i = last.openParenIndex + 1; i < offset; i++) {
            const ch = upto[i];
            if (inString) {
                if (ch === inString) {
                    inString = null;
                }
                continue;
            }
            if (ch === '"') {
                inString = ch;
                continue;
            }
            if (ch === '(') {
                depth++;
                continue;
            }
            if (ch === ')') {
                depth--;
                if (depth === 0) {
                    closed = true;
                }
                continue;
            }
            if (ch === ',') {
                if (!closed) {
                    if (depth === 1) {
                        insideCommas++;
                    }
                } else {
                    afterCommas++;
                }
            }
        }

        return {
            name: last.name,
            hadParens: true,
            inParens: !closed,
            insideCommas,
            afterCommas
        };
    }

    const noParenMatch = linePrefix.match(/(?:^|\s)([A-Za-z][A-Za-z0-9_]*)\s+([^()]*)$/);
    if (!noParenMatch) {
        return null;
    }

    const name = noParenMatch[1];
    if (!commandNamesSet.has(name)) {
        return null;
    }

    const paramsText = noParenMatch[2] || '';
    const afterCommas = (paramsText.match(/,/g) || []).length;

    return {
        name,
        hadParens: false,
        inParens: false,
        insideCommas: 0,
        afterCommas
    };
}



/**
 * Parse a single debug line and return all variable assignments on that line.
 * Returns an object: { varName: value, ... }
 *
 * Handles ADT debug patterns:
 *
 * 1) Direct assignment:
 *    SidPce= next_item(SidIt)                    <42>
 *    SidPceUse$ = get_obj_param(SidPce,"USE")     <"CLADDING BOARD">
 *
 * 1b) Inline then-assignment on if / else if (same line, then required):
 *    if TZ > CTopZ then CTopZ = TZ               <5127.43>
 *    else if TZ > CTopZ then CTopZ = TZ          <5127.43>
 *    Condition `=` is never treated as assignment.
 *    Bare true/false is the if-result — skip so a false branch does not write.
 *    Last <...> wins when both the if-result and then-value are present:
 *    if TZ > CTopZ then CTopZ = TZ  <true> _if_begin_ <5127.43>
 *    else VAR = (no then) is not a then-assignment.
 *
 * 2) Function with output in parens:
 *    vec_sub(NSP) SidPceSP,WP                     <-3300,254,2259.5>
 *    get_vxgeom_point(SidPceSP) SidGeom,"START"   <0,-11,2304.5>
 *
 * 3) Multi-output function (paren = input, rest = outputs):
 *    get_origin_pos(SidPce) SidP,SidX,SidY,SidZ  <0,-11,2304.5 , 0,1,0 , 0,0,1 , 1,0,0>
 *    Detected when: all args after paren are plain variable names AND
 *    count of ' , '-separated value groups matches count of output args.
 */
function parseLineAssignments(lineText) {
    const assignments = {};

    // Last <...> on the line is the dump value (optional trailing _if_begin_ etc.).
    // Using the last group so `<true> _if_begin_ <5127.43>` yields 5127.43, not the if-result.
    const lastAngleIdx = lineText.lastIndexOf('<');
    if (lastAngleIdx < 0) return assignments;

    const valueMatch = lineText.substring(lastAngleIdx).match(/^<(.+?)>\s*(?:_\w+_)?\s*$/);
    if (!valueMatch) return assignments;

    const rawValue = valueMatch[1].trim();

    // Skip empty values and loop counters (e.g. "22/~")
    if (rawValue === '' || /^\d+\//.test(rawValue)) return assignments;

    const codePart = lineText.substring(0, lastAngleIdx).trim();

    // ── Pattern 1: Direct assignment ──
    // Match: VARNAME = anything
    // Also matches VARNAME$ = anything (string vars)
    const assignMatch = codePart.match(/^\s*(\w+\$?)\s*=\s*/);
    if (assignMatch) {
        assignments[assignMatch[1]] = rawValue;
        return assignments;
    }

    // ── Pattern 1b: if / else if … then VAR = ──
    if (/^(?:else\s+)?if\b/i.test(codePart)) {
        const thenAssignMatches = [...codePart.matchAll(/\bthen\s+(\w+\$?)\s*=\s*/gi)];
        if (thenAssignMatches.length > 0) {
            // Bare true/false is the condition dump, not a then-write.
            if (/^(true|false)$/i.test(rawValue)) {
                return assignments;
            }
            const varName = thenAssignMatches[thenAssignMatches.length - 1][1];
            assignments[varName] = rawValue;
            return assignments;
        }
    }

    // ── Pattern 2 & 3: Function call ──
    // Match: funcname(parenArg) restOfArgs
    const funcMatch = codePart.match(/^\s*(\w+)\((\w+\$?)\)\s*(.*)/);
    if (funcMatch) {
        const parenArg = funcMatch[2];
        const restRaw = funcMatch[3].trim();

        if (restRaw) {
            // Split rest args by comma and trim
            const restParts = restRaw.split(',').map(a => a.trim());

            // Check if ALL parts are pure variable names (no literals)
            const varNamePattern = /^\w+\$?$/;
            const allAreVarNames = restParts.every(a => varNamePattern.test(a));

            if (allAreVarNames) {
                // Potential multi-output: split value by ' , ' (group separator)
                const valueGroups = rawValue.split(' , ').map(v => v.trim());

                if (restParts.length === valueGroups.length && restParts.length > 1) {
                    // Multi-output: paren is input, rest args are outputs
                    restParts.forEach((varName, idx) => {
                        assignments[varName] = valueGroups[idx];
                    });
                    return assignments;
                }
            }
        }

        // Default: paren is the output variable
        assignments[parenArg] = rawValue;
        return assignments;
    }

    return assignments;
}

/**
 * Build or retrieve cached assignment map for a document.
 * Returns Map<lineNumber, Map<varName, value>>
 */
function getDocumentAssignments(document) {
    const uri = document.uri.toString();
    const cached = docCache.get(uri);

    if (cached && cached.version === document.version) {
        return cached.assignments;
    }

    const assignments = new Map();

    const lines = document.getText().split(/\r?\n/);

    for (let i = 0; i < lines.length; i++) {
        const lineText = lines[i];
        const lineAssignments = parseLineAssignments(lineText);

        if (Object.keys(lineAssignments).length > 0) {
            assignments.set(i, lineAssignments);
        }
    }

    docCache.set(uri, { version: document.version, assignments });
    return assignments;
}

/**
 * Find the most recent value of a variable at or before the given line.
 */
function findMostRecentValue(document, line, varName) {
    const assignments = getDocumentAssignments(document);
    let lastValue = null;
    let lastLine = -1;

    for (let i = 0; i <= line; i++) {
        const lineAssign = assignments.get(i);
        if (lineAssign && lineAssign[varName] !== undefined) {
            lastValue = lineAssign[varName];
            lastLine = i;
        }
    }

    if (lastValue !== null) {
        return { value: lastValue, line: lastLine };
    }
    return null;
}

function resolveStringParam(document, upToLine, expr) {
    if (!expr) return null;
    expr = expr.trim();
    // Literal: "MACRO_CUSTOM" or 'BATHZONE'
    const literal = expr.match(/^["'](.*)["']$/);
    if (literal) return literal[1];
    // Variable: Library / Library$ — walk backwards for assignment
    const varName = extractBaseVariableName(expr);
    const lines = document.getText().split(/\r?\n/);
    for (let i = upToLine; i >= 0; i--) {
        const line = stripValidationComment(lines[i]);
        const m = line.match(new RegExp(`\\b${varName}\\s*=\\s*(.+)$`));
        if (!m) continue;
        const rhs = m[1].trim();
        const lit = rhs.match(/^["'](.*)["']/);
        if (lit) return lit[1];
    }
    return null;
}

function resolveMacroIdentity(document, varName, line) {
    const lines = document.getText().split(/\r?\n/);
    const baseName = extractBaseVariableName(varName);
    for (let i = line; i >= 0; i--) {
        const lineText = stripValidationComment(lines[i]);
        const assignRegex = new RegExp(`\\b${baseName}\\s*=\\s*new_macro\\s*\\(`, 'i');
        if (!assignRegex.test(lineText)) continue;
        const parsed = parseCommand(lineText.trim(), lineText.trim(), true);
        if (!parsed || parsed.functionName.toLowerCase() !== 'new_macro') continue;
        const library = resolveStringParam(document, i, parsed.insideParams[0]);
        const code = resolveStringParam(document, i, parsed.insideParams[1]);
        if (library && code) {
            return { library, code, line: i };
        }
    }
    return null;
}

function resolveJointIdentity(document, varName, line) {
    const lines = document.getText().split(/\r?\n/);
    const baseName = extractBaseVariableName(varName);
    for (let i = line; i >= 0; i--) {
        const lineText = stripValidationComment(lines[i]);
        const assignRegex = new RegExp(`\\b${baseName}\\s*=\\s*new_djoint\\s*\\(`, 'i');
        if (!assignRegex.test(lineText)) continue;
        const parsed = parseCommand(lineText.trim(), lineText.trim(), true);
        if (!parsed || parsed.functionName.toLowerCase() !== 'new_djoint') continue;
        const library = resolveStringParam(document, i, parsed.insideParams[0]);
        const code = resolveStringParam(document, i, parsed.insideParams[1]);
        if (library && code) {
            return { library, code, line: i };
        }
    }
    return null;
}

function resolveMacroLibraryPath (library) {
    if (!library) {
        return [];
    }

    // Get workspace folders from initialization
    let customname = "custom";
    if (workspaceFolders) {
        //loop through each workspaces folder.
        for (let i = 0; i < workspaceFolders.length; i++) {
            let workspaceFolder = workspaceFolders[i].uri;
            //check if the folder name contains "custom"
            if (workspaceFolder.includes("custom")) {
                //get the full name of that folder.
                customname = workspaceFolder.split('/').pop();
                //replace the %3A with : and replace the / with \
                customname = customname.replace(/\//g, '\\');
                customname = customname.replace('%3A', ':');
    }}}



    for (const folder of workspaceFolders) {
        try {
            if (folder.uri.includes(customname)) {
                //look for subfolder named complibs
                const CompleteUrl = folder.uri + '/complibs/' + library

                //create filesystem path from uri.
                const fsPath = fileURLToPath(CompleteUrl);
                return fsPath;;
            }} 
            catch (error) {
                console.error(`Error scanning for macro codes: ${error}`);
                return [];
            }}
    return [];
};

function getMacroRecordFields(library, code) {
    const libraryPath = resolveMacroLibraryPath(library); // reuse complibs lookup from getMacroCodes
    if (!libraryPath) return [];
    ensureMacroLibraryXmlExports(libraryPath);
    let xmlContent;
    const primaryXml = path.join(libraryPath, `d_${library}.xml`);
    try {
        xmlContent = fs.readFileSync(primaryXml, 'utf8');
    } catch {
        xmlContent = fs.readFileSync(path.join(libraryPath, 'd_FRM_SHEET.xml'), 'utf8');
    }
    const xmlDoc = new DOMParser().parseFromString(xmlContent, 'text/xml');
    const records = xmlDoc.getElementsByTagName('Record');
    for (let i = 0; i < records.length; i++) {
        const record = records[i];
        const cells = record.getElementsByTagName('Cell');
        let matched = false;
        const fields = [];
        for (let j = 0; j < cells.length; j++) {
            const cell = cells[j];
            const name = cell.getAttribute('Name');
            const value = cell.textContent?.trim() ?? '';
            if (name === 'CODE' || name === 'SHTCODE') {
                if (value.toUpperCase() === code.toUpperCase()) matched = true;
            }
            if (name) fields.push({ name, value });
        }
        if (matched) {
            return fields
                //.filter(f => f.name && f.name !== 'CODE' && f.name !== 'SHTCODE') // optional: skip key fields
                .map(f => ({
                    label: f.name,
                    documentation: `Value in database: ${f.value}`,
                    detail: `Macro field (${library}/${code})`,
                    insertText: `"${f.name}"`
                }));
        }
    }
    return [];
}

