function CleanUpLineFunc(lineText) {
    const commentIndex = findValidationCommentIndex(lineText);
    const code = commentIndex !== -1 ? lineText.substring(0, commentIndex) : lineText;
    const comment = commentIndex !== -1 ? lineText.substring(commentIndex) : '';
    const parsed = parseCommand(code.trim(), code.trim(), false);
    //get the cleanup rules for the function
    const cleanupRules = commandValidations[parsed.functionName.toLowerCase()].cleanupRules;
    if (!cleanupRules) {
        return null;
    }
    //apply the cleanup rules to the parameters
    const params = [...parsed.afterParams];
    let paramIndex = 0;
    for (const rule of cleanupRules.afterParams) {
        if (rule.quote === 'bareNumericLiteral' && /^\d+(\.\d+)?$/.test(params[paramIndex].trim())) {
            params[paramIndex] = `"${params[paramIndex].trim()}"`;
            paramIndex++;
        } else if (rule.quote === 'always') {
            params[paramIndex] = `"${params[paramIndex].trim()}"`;
            paramIndex++;
        } else if (rule.quote === 'never') {
            paramIndex++;
        }
    }
    const rebuilt =
        `${parsed.functionName}(${parsed.insideParams.join(', ')}) ` +
        params.join(', ') +
        comment;
    return rebuilt;
}


